NAME = 'VulgSistine: Vulgata Sistina'
BOOK = 'I Maccabees'

CHAPTERS = {
    1: {
        1: 'Et factum est, postquam percussit Alexander Philippi Macedo, qui primus regnavit in Graecia, egressus de terra Cethim, Darium regem Persarum, et Medorum:',
        2: 'constituit praelia multa, et obtinuit omnium munitiones, et interfecit reges terrae,',
        3: 'et pertransiit usque ad fines terrae: et accepit spolia multitudinis Gentium: et siluit terra in conspectu eius.',
        4: 'Et congregavit virtutem, et exercitum fortem nimis: et exaltatum est, et elevatum cor eius:',
        5: 'et obtinuit regiones Gentium, et tyrannos: et facti sunt illi in tributum.',
        6: 'Et post haec decidit in lectum, et cognovit quia moreretur.',
        7: 'Et vocavit pueros suos nobiles, qui secum erant nutriti a iuventute: et divisit illis regnum suum, cum adhuc viveret.',
        8: 'Et regnavit Alexander annis duodecim, et mortuus est.',
        9: 'Et obtinuerunt pueri eius regnum, unusquisque in loco suo:',
        10: 'et imposuerunt omnes sibi diademata post mortem eius, et filii eorum post eos annis multis, et multiplicata sunt mala in terra.',
        11: 'Et exiit ex eis radix peccati, Antiochus illustris, filius Antiochi regis, qui fuerat Romae obses: et regnavit in anno centesimo trigesimo septimo regni Graecorum.',
        12: 'In diebus illis, exierunt ex Israel filii iniqui, et suaserunt multis, dicentes: Eamus, et disponamus testamentum cum Gentibus, quae circa nos sunt: quia ex quo recessimus ab eis, invenerunt nos multa mala.',
        13: 'Et bonus visus est sermo in oculis eorum.',
        14: 'Et destinaverunt aliqui de populo, et abierunt ad regem: et dedit illis potestatem ut facerent iustitiam Gentium.',
        15: 'Et aedificaverunt gymnasium in Ierosolymis secundum leges Nationum:',
        16: 'et fecerunt sibi praeputia, et recesserunt a testamento sancto, et iuncti sunt Nationibus, et venundati sunt ut facerent malum.',
        17: 'Et paratum est regnum in conspectu Antiochi, et coepit regnare in terra Aegypti ut regnaret super duo regna.',
        18: 'Et intravit in Aegyptum in multitudine gravi, in curribus, et elephantis, et equitibus, et copiosa navium multitudine:',
        19: 'et constituit bellum adversus Ptolemaeum regem Aegypti, et veritus est Ptolemaeus a facie eius, et fugit, et ceciderunt vulnerati multi.',
        20: 'Et comprehendit civitates munitas in terra Aegypti: et accepit spolia Terrae Aegypti.',
        21: 'Et convertit Antiochus, postquam percussit Aegyptum in centesimo et quadragesimo tertio anno: et ascendit ad Israel,',
        22: 'et ascendit Ierosolymam in multitudine gravi.',
        23: 'Et intravit in sanctificationem cum superbia, et accepit altare aureum, et candelabrum luminis, et universa vasa eius, et mensam propositionis, et libatoria, et phialas, et mortariola aurea, et velum, et coronas, et ornamentum aureum, quod in facie templi erat: et comminuit omnia.',
        24: 'Et accepit argentum, et aurum, et vasa concupiscibilia: et accepit thesauros occultos, quos invenit: et sublatis omnibus abiit in terram suam.',
        25: 'Et fecit caedem hominum, et locutus est in superbia magna.',
        26: 'Et factus est planctus magnus in Israel, et in omni loco eorum:',
        27: 'et ingemuerunt principes, et seniores: virgines, et iuvenes infirmati sunt: et speciositas mulierum immutata est.',
        28: 'Omnis maritus sumpsit lamentum: et quae sedebant in thoro maritali, lugebant:',
        29: 'et commota est terra super habitantes in ea, et universa domus Iacob induit confusionem.',
        30: 'Et post duos annos dierum misit rex principem tributorum in civitates Iuda, et venit Ierusalem cum turba magna.',
        31: 'Et locutus est ad eos verba pacifica in dolo: et crediderunt ei.',
        32: 'Et irruit super civitatem repente, et percussit eam plaga magna, et perdidit populum multum ex Israel.',
        33: 'Et accepit spolia civitatis: et succendit eam igne, et destruxit domos eius, et muros eius in circuitu:',
        34: 'et captivas duxerunt mulieres: et natos, et pecora possederunt.',
        35: 'Et aedificaverunt civitatem David muro magno, et firmo, et turribus firmis, et facta est illis in arcem:',
        36: 'et posuerunt illic gentem peccatricem viros iniquos, et convaluerunt in ea. et posuerunt arma, et escas, et congregaverunt spolia Ierusalem:',
        37: 'et reposuerunt illic: et facti sunt in laqueum magnum.',
        38: 'Et factum est hoc ad insidias sanctificationi, et in diabolum malum in Israel:',
        39: 'et effuderunt sanguinem innocentem per circuitum sanctificationis, et contaminaverunt sanctificationem.',
        40: 'Et fugerunt habitatores Ierusalem propter eos, et facta est habitatio exterorum, et facta est extera semini suo, et nati eius reliquerunt eam.',
        41: 'Sanctificatio eius desolata est sicut solitudo, dies festi eius conversi sunt in luctum, sabbata eius in opprobrium, honores eius in nihilum.',
        42: 'Secundum gloriam eius multiplicata est ignominia eius: et sublimitas eius conversa est in luctum.',
        43: 'Et scripsit rex Antiochus omni regno suo ut esset omnis populus, unus: et relinqueret unusquisque legem suam.',
        44: 'Et consenserunt omnes Gentes secundum verbum regis Antiochi:',
        45: 'et multi ex Israel consenserunt servituti eius, et sacrificaverunt idolis, et coinquinaverunt sabbatum.',
        46: 'Et misit rex libros per manus nunciorum in Ierusalem, et in omnes civitates Iuda: ut sequerentur leges Gentium terrae,',
        47: 'et prohiberent holocausta, et sacrificia, et placationes fieri in templo Dei,',
        48: 'et prohiberent celebrari sabbatum, et dies sollemnes:',
        49: 'et iussit coinquinari sancta, et sanctum populum Israel.',
        50: 'Et iussit aedificari aras, et templa, et idola, et immolari carnes suillas, et pecora communia,',
        51: 'et relinquere filios suos incircumcisos, et coinquinari animas eorum in omnibus immunditiis, et abominationibus, ita ut obliviscerentur legem, et immutarent omnes iustificationes Dei.',
        52: 'Et quicumque non fecissent secundum verbum regis Antiochi, morerentur.',
        53: 'Secundum omnia verba haec scripsit omni regno suo: et praeposuit principes populo, qui haec fieri cogerent.',
        54: 'Et iusserunt civitatibus Iuda sacrificare.',
        55: 'Et congregati sunt multi de populo ad eos, qui dereliquerant legem Domini: et fecerunt mala super terram:',
        56: 'et effugaverunt populum Israel in abditis, et in absconditis fugitivorum locis.',
        57: 'Die quintadecima mensis Casleu, quinto et quadragesimo et centesimo anno aedificavit rex Antiochus abominandum idolum desolationis super altare Dei, et per universas civitates Iuda in circuitu aedificaverunt aras:',
        58: 'et ante ianuas domorum et in plateis incendebant thura, et sacrificabant:',
        59: 'et libros legis Dei combusserunt igne, scindentes eos:',
        60: 'et apud quemcumque inveniebantur libri testamenti Domini, et quicumque observabat legem Domini, secundum edictum regis trucidabant eum.',
        61: 'In virtute sua faciebant haec populo Israel, qui inveniebatur in omni mense et mense in civitatibus.',
        62: 'Et quinta et vigesima die mensis sacrificabant super aram, quae erat contra altare.',
        63: 'Et mulieres, quae circumcidebant filios suos, trucidabantur secundum iussum regis Antiochi,',
        64: 'et suspendebant pueros a cervicibus per universas domos eorum: et eos, qui circumciderant illos, trucidabant.',
        65: 'Et multi de populo Israel definierunt apud se, ut non manducarent immunda: et elegerunt magis mori, quam cibis coinquinari immundis:',
        66: 'et noluerunt infringere legem Dei sanctam, et trucidati sunt:',
        67: 'et facta est ira magna super populum Israel valde.',
    },
    2: {
        1: 'In diebus illis surrexit Mathathias filius Ioannis, filii Simeonis, sacerdos ex filiis Ioarim ab Ierusalem, et consedit in monte Modin:',
        2: 'et habebat filios quinque, Ioannem, qui cognominabatur Gaddis:',
        3: 'et Simonem, qui cognominabatur Thasi:',
        4: 'et Iudam, qui vocabatur Machabaeus:',
        5: 'et Eleazarum, qui cognominabatur Abaron: et Ionathan, qui cognominabatur Apphus.',
        6: 'hi viderunt mala, quae fiebant in populo Iuda, et in Ierusalem.',
        7: 'Et dixit Mathathias: Vae mihi, ut quid natus sum videre contritionem populi mei, et contritionem civitatis sanctae, et sedere illic, cum datur in manibus inimicorum?',
        8: 'Sancta in manu extraneorum facta sunt: templum eius sicut homo ignobilis.',
        9: 'Vasa gloriae eius captiva abducta sunt: trucidati sunt senes eius in plateis, et iuvenes eius ceciderunt in gladio inimicorum.',
        10: 'Quae gens non hereditavit regnum eius, et non obtinuit spolia eius?',
        11: 'Omnis compositio eius ablata est. Quae erat libera, facta est ancilla.',
        12: 'Et ecce sancta nostra, et pulchritudo nostra, et claritas nostra desolata est, et coinquinaverunt ea Gentes.',
        13: 'Quo ergo nobis adhuc vivere?',
        14: 'Et scidit vestimenta sua Mathathias, et filii eius: et operuerunt se ciliciis, et planxerunt valde.',
        15: 'Et venerunt illuc qui missi erant a rege Antiocho, ut cogerent eos, qui confugerant in civitatem Modin, immolare, et accendere thura, et a lege Dei discedere.',
        16: 'Et multi de populo Israel consentientes accesserunt ad eos: sed Mathathias, et filii eius constanter steterunt.',
        17: 'Et respondentes qui missi erant ab Antiocho, dixerunt Mathathiae: Princeps et clarissimus, et magnus es in hac civitate, et ornatus filiis, et fratribus.',
        18: 'ergo accede prior, et fac iussum regis, sicut fecerunt omnes Gentes, et viri Iuda, et qui remanserunt in Ierusalem: et eris tu, et filii tui inter amicos regis, et amplificatus auro, et argento, et muneribus multis.',
        19: 'Et respondit Mathathias, et dixit magna voce: Et si omnes Gentes regi Antiocho obediunt, ut discedat unusquisque a servitute legis patrum suorum, et consentiat mandatis eius:',
        20: 'ego et filii mei, et fratres mei obediemus legi patrum nostrorum.',
        21: 'propitius sit nobis Deus: non est nobis utile relinquere legem, et iustitias Dei:',
        22: 'non audiemus verba regis Antiochi, nec sacrificabimus transgredientes legis nostrae mandata, ut eamus altera via.',
        23: 'Et ut cessavit loqui verba haec, accessit quidam Iudaeus in omnium oculis sacrificare idolis super aram in civitate Modin, secundum iussum regis:',
        24: 'et vidit Mathathias, et doluit, et contremuerunt renes eius, et accensus est furor eius secundum iudicium legis, et insiliens trucidavit eum super aram:',
        25: 'sed et virum, quem rex Antiochus miserat, qui cogebat immolare, occidit in ipso tempore, et aram destruxit,',
        26: 'et zelatus est legem, sicut fecit Phinees Zamri filio Salomi.',
        27: 'Et exclamavit Mathathias voce magna in civitate, dicens: Omnis, qui zelum habet legis statuens testamentum, exeat post me.',
        28: 'Et fugit ipse, et filii eius in montes, et reliquerunt quaecumque habebant in civitate.',
        29: 'Tunc descenderunt multi quaerentes iudicium, et iustitiam, in desertum:',
        30: 'et sederunt ibi ipsi, et filii, et mulieres eorum, et pecora eorum: quoniam inundaverunt super eos mala.',
        31: 'Et renunciatum est viris regis, et exercitui, qui erat in Ierusalem civitate David quoniam discessissent viri quidam, qui dissipaverunt mandatum regis in loca occulta in deserto, et abiissent post illos multi.',
        32: 'Et statim perrexerunt ad eos, et constituerunt adversus eos praelium in die sabbatorum,',
        33: 'et dixerunt ad eos: Resistitis et nunc adhuc? exite, et facite secundum verbum regis Antiochi, et vivetis.',
        34: 'Et dixerunt: Non exibimus, neque faciemus verbum regis, ut polluamus diem sabbatorum.',
        35: 'Et concitaverunt adversus eos praelium.',
        36: 'Et non responderunt eis, nec lapidem miserunt in eos, nec oppilaverunt loca occulta,',
        37: 'dicentes: Moriamur omnes in simplicitate nostra: et testes erunt super nos caelum, et terra, quod iniuste perditis nos.',
        38: 'Et intulerunt illis bellum sabbatis: et mortui sunt ipsi, et uxores eorum, et filii eorum, et pecora eorum usque ad mille animas hominum.',
        39: 'Et cognovit Mathathias, et amici eius, et luctum habuerunt super eos valde.',
        40: 'Et dixit vir proximo suo: Si omnes fecerimus sicut fratres nostri fecerunt, et non pugnaverimus adversus gentes pro animabus nostris, et iustificationibus nostris: nunc citius disperdent nos a terra.',
        41: 'Et cogitaverunt in die illa, dicentes: Omnis homo, quicumque venerit ad nos in bello die sabbatorum, pugnemus adversus eum: et non moriemur omnes, sicut mortui sunt fratres nostri in occultis.',
        42: 'Tunc congregata est ad eos synagoga Assidaeorum fortis viribus ex Israel, omnis voluntarius in lege:',
        43: 'et omnes, qui fugiebant a malis, additi sunt ad eos, et facti sunt illis ad firmamentum.',
        44: 'Et collegerunt exercitum, et percusserunt peccatores in ira sua, et viros iniquos in indignatione sua: et ceteri fugerunt ad nationes, ut evaderent.',
        45: 'Et circuivit Mathathias, et amici eius, et destruxerunt aras:',
        46: 'et circumciderunt pueros incircumcisos quotquot invenerunt in finibus eorum: et in fortitudine.',
        47: 'Et persecuti sunt filios superbiae, et prosperatum est opus in manibus eorum:',
        48: 'et obtinuerunt legem de manibus gentium, et de manibus regum: et non dederant cornu peccatori.',
        49: 'Et appropinquaverunt dies Mathathiae moriendi, et dixit filiis suis: Nunc confortata est superbia, et castigatio, et tempus eversionis, et ira indignationis:',
        50: 'Nunc ergo, o filii, aemulatores estote legis, et date animas vestras pro testamento patrum vestrorum,',
        51: 'et mementote operum patrum, quae fecerunt in generationibus suis: et accipietis gloriam magnam, et nomen aeternum.',
        52: 'Abraham nonne in tentatione inventus est fidelis, et reputatum est ei ad iustitiam?',
        53: 'Ioseph in tempore angustiae suae custodivit mandatum, et factus est dominus Aegypti.',
        54: 'Phinees pater noster, zelando zelum Dei, accepit testamentum sacerdotii aeterni.',
        55: 'Iesus dum implevit verbum, factus est dux in Israel.',
        56: 'Caleb, dum testificatur in ecclesia, accepit hereditatem.',
        57: 'David in sua misericordia consecutus est sedem regni in saecula.',
        58: 'Elias, dum zelat zelum legis, receptus est in caelum.',
        59: 'Ananias et Azarias et Misael credentes, liberati sunt de flamma.',
        60: 'Daniel in sua simplicitate liberatus est de ore leonum.',
        61: 'Et ita cogitate per generationem, et generationem: quia omnes qui sperant in eum, non infirmantur.',
        62: 'Et a verbis viri peccatoris ne timueritis: quia gloria eius stercus, et vermis est:',
        63: 'hodie extollitur, et cras non invenietur: quia conversus est in terram suam, et cogitatio eius periit.',
        64: 'Vos ergo filii confortamini, et viriliter agite in lege: quia in ipsa gloriosi eritis.',
        65: 'Et ecce Simon frater vester, scio quod vir consilii est: ipsum audite semper, et ipse erit vobis pater.',
        66: 'Et Iudas Machabaeus fortis viribus a iuventute sua, sit vobis princeps militiae, et ipse aget bellum populi.',
        67: 'Et adducetis ad vos omnes factores legis: et vindicate vindictam populi vestri.',
        68: 'Retribuite retributionem Gentibus, et intendite in praeceptum legis.',
        69: 'Et benedixit eos, et appositus est ad patres suos.',
        70: 'Et defunctus est anno centesimo et quadragesimo sexto: et sepultus est a filiis suis in sepulchris patrum suorum in Modin, et planxerunt eum omnis Israel planctu magno.',
    },
    3: {
        1: 'Et surrexit Iudas, qui vocabatur Machabaeus filius eius pro eo:',
        2: 'et adiuvabant eum omnes fratres eius: et universi, qui se coniunxerant patri eius, et praeliabantur praelium Israel cum laetitia.',
        3: 'Et dilatavit gloriam populo suo, et induit se loricam sicut gigas, et succinxit se arma bellica sua in praeliis, et protegebat castra gladio suo.',
        4: 'Similis factus est leoni in operibus suis, et sicut catulus leonis rugiens in venatione.',
        5: 'Et persecutus est iniquos perscrutans eos: et qui conturbabant populum suum, eos succendit flammis:',
        6: 'et repulsi sunt inimici eius prae timore eius, et omnes operarii iniquitatis conturbati sunt: et directa est salus in manu eius.',
        7: 'Et exacerbabat reges multos, et laetificabat Iacob in operibus suis, et in saeculum memoria eius in benedictione.',
        8: 'Et perambulavit civitates Iuda, et perdidit impios ex eis, et avertit iram ab Israel.',
        9: 'Et nominatus est usque ad novissimum terrae, et congregavit pereuntes.',
        10: 'Et congregavit Apollonius Gentes, et a Samaria virtutem multam et magnam ad bellandum contra Israel.',
        11: 'Et cognovit Iudas, et exiit obviam illi: et percussit, et occidit illum: et ceciderunt vulnerati multi, et reliqui fugerunt.',
        12: 'et accepit spolia eorum: et gladium Apollonii abstulit Iudas, et erat pugnans in eo omnibus diebus.',
        13: 'Et audivit Seron princeps exercitus Syriae, quod congregavit Iudas congregationem fidelium, et ecclesiam secum,',
        14: 'et ait: Faciam mihi nomen, et glorificabor in regno, et debellabo Iudam, et eos, qui cum ipso sunt, qui spernebant verbum regis.',
        15: 'Et praeparavit se: et ascenderunt cum eo castra impiorum fortes auxiliarii ut facerent vindictam in filios Israel.',
        16: 'Et appropinquaverunt usque ad Bethoron: et exivit Iudas obviam illi cum paucis.',
        17: 'Ut autem viderunt exercitum venientem sibi obviam, dixerunt Iudae: Quomodo poterimus pauci pugnare contra multitudinem tantam, et tam fortem, et nos fatigati sumus ieiunio hodie?',
        18: 'Et ait Iudas: Facile est concludi multos in manus paucorum: et non est differentia in conspectu Dei caeli liberare in multis, et in paucis:',
        19: 'quoniam non in multitudine exercitus victoria belli, sed de caelo fortitudo est.',
        20: 'Ipsi veniunt ad nos in multitudine contumaci, et superbia ut disperdant nos, et uxores nostras, et filios nostros, et ut spolient nos:',
        21: 'nos vero pugnabimus pro animabus nostris, et legibus nostris:',
        22: 'et ipse Dominus conteret eos ante faciem nostram: vos autem ne timueritis eos.',
        23: 'Ut cessavit autem loqui, insiluit in eos subito: et contritus est Seron, et exercitus eius in conspectu ipsius:',
        24: 'et persecutus est eum in descensu Bethoron usque in campum, et ceciderunt ex eis octingenti viri, reliqui autem fugerunt in terram Philisthiim.',
        25: 'Et cecidit timor Iudae, ac fratrum eius, et formido super omnes gentes in circuitu eorum.',
        26: 'et pervenit ad regem nomen eius, et de praeliis Iudae narrabant omnes gentes.',
        27: 'Ut audivit autem rex Antiochus sermones istos, iratus est animo: et misit, et congregavit exercitum universi regni sui, castra fortia valde:',
        28: 'et aperuit aerarium suum, et dedit stipendia exercitui in annum: et mandavit illis ut essent parati ad omnia.',
        29: 'Et vidit quod defecit pecunia de thesauris suis, et tributa regionis modica propter dissensionem, et plagam, quam fecit in terra, ut tollerent legitima, quae erant a primis diebus:',
        30: 'et timuit ne non haberet et semel et bis, in sumptus et donaria, quae dederat ante larga manu: et abundaverat super reges, qui ante eum fuerant.',
        31: 'Et consternatus erat animo valde, et cogitavit ire in Persidem, et accipere tributa regionum, et congregare argentum multum.',
        32: 'Et reliquit Lysiam hominem nobilem de genere regali, super negotia regia, a flumine Euphrate usque ad flumen Aegypti:',
        33: 'et ut nutriret Antiochum filium suum, donec rediret.',
        34: 'Et tradidit ei medium exercitum, et elephantos: et mandavit ei de omnibus, quae volebat, et de inhabitantibus Iudaeam, et Ierusalem:',
        35: 'et ut mitteret ad eos exercitum ad conterendam, et extirpandam virtutem Israel, et reliquias Ierusalem, et auferendam memoriam eorum de loco:',
        36: 'et ut constitueret habitatores filios alienigenas in omnibus finibus eorum, et sorte distribueret terram eorum.',
        37: 'Et rex assumpsit partem exercitus residui, et exivit ab Antiochia civitate regni sui anno centesimo et quadragesimo septimo: et transfretavit Euphraten flumen, et perambulabat superiores regiones.',
        38: 'Et elegit Lysias Ptolemaeum filium Dorymini, et Nicanorem, et Gorgiam, viros potentes ex amicis regis:',
        39: 'et misit cum eis quadraginta millia virorum, et septem millia equitum ut venirent in terram Iuda, et disperderent eam secundum verbum regis.',
        40: 'Et processerunt cum universa virtute sua, et venerunt, et applicuerunt Emmaum in terra campestri.',
        41: 'Et audierunt mercatores regionum nomen eorum: et acceperunt argentum, et aurum multum valde, et pueros: et venerunt in castra ut acciperent filios Israel in servos, et additi sunt ad eos exercitus Syriae, et terrae alienigenarum.',
        42: 'Et vidit Iudas, et fratres eius, quia multiplicata sunt mala, et exercitus applicabant ad fines eorum: et cognoverunt verba regis, quae mandavit populo facere in interitum, et consummationem:',
        43: 'et dixerunt unusquisque ad proximum suum: Erigamus deiectionem populi nostri, et pugnemus pro populo nostro, et sanctis nostris.',
        44: 'Et congregatus est conventus ut essent parati in praelium: et ut orarent, et peterent misericordiam, et miserationes.',
        45: 'Et Ierusalem non habitabatur, sed erat sicut desertum: non erat qui ingrederetur et egrederetur de natis eius: et sanctum conculcabatur: et filii alienigenarum erant in arce, ibi erat habitatio Gentium: et ablata est voluptas a Iacob, et defecit ibi tibia, et cithara.',
        46: 'Et congregati sunt, et venerunt in Maspha contra Ierusalem: quia locus orationis erat in Maspha ante in Israel.',
        47: 'Et ieiunaverunt illa die, et induerunt se ciliciis, et cinerem imposuerunt capiti suo: et disciderunt vestimenta sua:',
        48: 'et expanderunt libros legis, de quibus scrutabantur Gentes similitudinem simulacrorum suorum:',
        49: 'et attulerunt ornamenta sacerdotalia, et primitias, et decimas: et suscitaverunt Nazaraeos, qui impleverant dies:',
        50: 'et clamaverunt voce magna in caelum, dicentes: Quid faciemus istis, et quo eos ducemus?',
        51: 'et sancta tua conculcata sunt, et contaminata sunt, et sacerdotes tui facti sunt in luctum, et in humilitatem.',
        52: 'et ecce Nationes convenerunt adversum nos ut nos disperdant: tu scis quae cogitant in nos.',
        53: 'Quomodo poterimus subsistere ante faciem eorum, nisi tu Deus adiuves nos?',
        54: 'Et tubis exclamaverunt voce magna.',
        55: 'Et post haec constituit Iudas duces populi, tribunos, et centuriones, et pentacontarchos, et decuriones.',
        56: 'Et dixit his, qui aedificabant domos, et sponsabant uxores, et plantabant vineas, et formidolosis, ut redirent unusquisque in domum suam secundum legem.',
        57: 'Et moverunt castra, et collocaverunt ad Austrum Emmaum.',
        58: 'Et ait Iudas: Accingimini, et estote filii potentes, et estote parati in mane, ut pugnetis adversus Nationes has, quae convenerunt adversus nos disperdere nos, et sancta nostra:',
        59: 'quoniam melius est nos mori in bello, quam videre mala gentis nostrae, et sanctorum.',
        60: 'Sicut autem fuerit voluntas in caelo, sic fiat.',
    },
    4: {
        1: 'Et assumpsit Gorgias quinque millia virorum, et mille equites electos: et moverunt castra nocte',
        2: 'ut applicarent ad castra Iudaeorum, et percuterent eos subito: et filii, qui erant ex arce, erant illis duces.',
        3: 'Et audivit Iudas, et surrexit ipse et potentes percutere virtutem exercituum regis, qui erant in Emmaum.',
        4: 'Adhuc enim dispersus erat exercitus a castris.',
        5: 'Et venit Gorgias in castra Iudae noctu, et neminem invenit, et quaerebat eos in montibus: quoniam dixit: Fugiunt hi a nobis.',
        6: 'Et cum dies factus esset, apparuit Iudas in campo cum tribus millibus virorum tantum: qui tegumenta, et gladios non habebant:',
        7: 'et viderunt castra Gentium valida, et loricatos, et equitatus in circuitu eorum, et hi docti ad praelium.',
        8: 'Et ait Iudas viris, qui secum erant: Ne timueritis multitudinem eorum, et impetum eorum ne formidetis.',
        9: 'Mementote qualiter salvi facti sunt patres nostri in mari rubro, cum sequeretur eos Pharao cum exercitu multo.',
        10: 'Et nunc clamemus in caelum: et miserebitur nostri Dominus, et memor erit testamenti patrum nostrorum, et conteret exercitum istum ante faciem nostram hodie:',
        11: 'et scient omnes gentes quia est Deus qui redimat, et liberet Israel.',
        12: 'Et elevaverunt alienigenae oculos suos, et viderunt eos venientes ex adverso.',
        13: 'Et exierunt de castris in praelium, et tuba cecinerunt hi, qui erant cum Iuda:',
        14: 'Et congressi sunt: et contritae sunt Gentes, et fugerunt in campum.',
        15: 'Novissimi autem omnes ceciderunt in gladio, et persecuti sunt eos usque Gezeron, et usque in campos Idumaeae, et Azoti, et Iamniae: et ceciderunt ex illis usque ad tria millia virorum.',
        16: 'Et reversus est Iudas, et exercitus eius, sequens eum.',
        17: 'Dixitque ad populum: Non concupiscaris spolia: quia bellum contra nos est,',
        18: 'et Gorgias et exercitus eius prope nos in monte: sed state nunc contra inimicos nostros, et expugnate eos, et sumetis postea spolia securi.',
        19: 'Et adhuc loquente Iuda haec, ecce apparuit pars quaedam prospiciens de monte.',
        20: 'Et vidit Gorgias quod in fugam conversi sunt sui, et succenderunt castra: fumus enim, qui videbatur, declarabat quod factum est.',
        21: 'Quibus illi conspectis timuerunt valde, aspicientes simul et Iudam, et exercitum in campo paratum ad praelium.',
        22: 'Et fugerunt omnes in campum alienigenarum:',
        23: 'et Iudas reversus est ad spolia castrorum, et acceperunt aurum multum, et argentum, et hyacinthinum, et purpuram marinam, et opes magnas.',
        24: 'Et conversi, hymnum canebant, et benedicebant Deum in caelum, quoniam bonus est, quoniam in saeculum misericordia eius.',
        25: 'Et facta est salus magna in Israel in die illa.',
        26: 'Quicumque autem alienigenarum evaserunt, venerunt, et nunciaverunt Lysiae universa, quae acciderant.',
        27: 'Quibus ille auditis consternatus animo deficiebat: quod non qualia voluit, talia contigerunt in Israel, et qualia mandavit rex.',
        28: 'Et sequenti anno congregavit Lysias virorum electorum sexaginta millia, et equitum quinque millia, ut debellaret eos.',
        29: 'Et venerunt in Iudaeam, et castra posuerunt in Bethoron, et occurrit illis Iudas cum decem millibus viris.',
        30: 'Et viderunt exercitum fortem, et oravit, et dixit: Benedictus es salvator Israel, qui contrivisti impetum potentis in manu servi tui David, et tradidisti castra alienigenarum in manu Ionathae filii Saul, et armigeri eius.',
        31: 'Conclude exercitum istum in manu populi tui Israel, et confundantur in exercitu suo, et equitibus.',
        32: 'Da illis formidinem, et tabefac audaciam virtutis eorum, et commoveantur contritione sua.',
        33: 'Deiice illos gladio diligentium te: et collaudent te omnes, qui noverunt nomen tuum in hymnis.',
        34: 'Et commiserunt praelium: et ceciderunt de exercitu Lysiae quinque millia virorum.',
        35: 'Videns autem Lysias fugam suorum, et Iudaeorum audaciam, et quod parati sunt aut vivere, aut mori fortiter, abiit Antiochiam, et elegit milites, ut multiplicati rursus venirent in Iudaeam.',
        36: 'Dixit autem Iudas, et fratres eius: Ecce contriti sunt inimici nostri: ascendamus nunc mundare sancta, et renovare.',
        37: 'Et congregatus est omnis exercitus, et ascenderunt in montem Sion.',
        38: 'Et viderunt sanctificationem desertam, et altare profanatum, et portas exustas, et in atriis virgulta nata sicut in saltu, vel in montibus, et pastophoria diruta.',
        39: 'Et sciderunt vestimenta sua, et planxerunt planctu magno, et imposuerunt cinerem super caput suum.',
        40: 'et ceciderunt in faciem super terram, et exclamaverunt tubis signorum, et clamaverunt in caelum.',
        41: 'Tunc ordinavit Iudas viros ut pugnarent adversus eos, qui erant in arce, donec emundarent sancta.',
        42: 'Et elegit sacerdotes sine macula, voluntatem habentes in lege Dei:',
        43: 'et mundaverunt sancta, et tulerunt lapides contaminationis in locum immundum.',
        44: 'Et cogitavit de altari holocaustorum, quod profanatum erat, quid de eo faceret.',
        45: 'Et incidit illis consilium bonum ut destruerent illud: ne forte illis esset in opprobrium, quia contaminaverunt illud Gentes, et demoliti sunt illud.',
        46: 'Et reposuerunt lapides in monte domus in loco apto, quoadusque veniret propheta, et responderet de eis.',
        47: 'Et acceperunt lapides integros secundum legem, et aedificaverunt altare novum secundum illud, quod fuit prius:',
        48: 'et aedificaverunt sancta, et quae intra domum erant intrinsecus: et aedem, et atria sanctificaverunt.',
        49: 'Et fecerunt vasa sancta nova, et intulerunt candelabrum, et altare incensorum, et mensam in templum.',
        50: 'Et incensum posuerunt super altare, et accenderunt lucernas quae super candelabrum erant, et lucebant in templo.',
        51: 'Et posuerunt super mensam panes, et appenderunt vela, et consummaverunt omnia opera, quae fecerant.',
        52: 'Et ante matutinum surrexerunt quinta et vigesima die mensis noni (hic est mensis Casleu) centesimi quadragesimi octavi anni:',
        53: 'et obtulerunt sacrificium secundum legem super altare holocaustorum novum, quod fecerunt.',
        54: 'Secundum tempus et secundum diem, in qua contaminaverunt illud gentes, in ipsa renovatum est in canticis, et citharis, et cinyris, et in cymbalis.',
        55: 'Et cecidit omnis populus in faciem, et adoraverunt, et benedixerunt in caelum eum, qui prosperavit eis.',
        56: 'Et fecerunt dedicationem altaris diebus octo, et obtulerunt holocausta cum laetitia, et sacrificium salutaris et laudis.',
        57: 'Et ornaverunt faciem templi coronis aureis, et scutulis: et dedicaverunt portas, et pastophoria, et imposuerunt eis ianuas.',
        58: 'Et facta est laetitia in populo magna valde, et aversum est opprobrium Gentium.',
        59: 'Et statuit Iudas, et fratres eius, et universa ecclesia Israel ut agatur dies dedicationis altaris in temporibus suis ab anno in annum per dies octo a quinta et vigesima die mensis Casleu, cum laetitia et gaudio.',
        60: 'et aedificaverunt in tempore illo montem Sion, et per circuitum muros altos, et turres firmas, nequando venirent Gentes, et conculcarent eum sicut antea fecerunt.',
        61: 'Et collocavit illic exercitum, ut servarent eum, et munivit eum ad custodiendum Bethsuram, ut haberet populus munitionem contra faciem Idumaeae.',
    },
    5: {
        1: 'Et factum est, ut audierunt Gentes in circuitu quia aedificatum est altare, et sanctuarium sicut prius, iratae sunt valde:',
        2: 'et cogitabant tollere genus Iacob, qui erant inter eos, et coeperunt occidere de populo, et persequi.',
        3: 'Et debellabat Iudas filios Esau in Idumaea, et eos, qui erant in Arabathane: quia circumsedebant Israelitas, et percussit eos plaga magna.',
        4: 'Et recordatus est malitiam filiorum Bean, qui erant populo in laqueum et in scandalum, insidiantes ei in via.',
        5: 'Et conclusi sunt ab eo in turribus, et applicuit ad eos, et anathematizavit eos, et incendit turres eorum igni cum omnibus, qui in eis erant.',
        6: 'Et transivit ad filios Ammon, et invenit manum fortem, et populum copiosum, et Timotheum ducem ipsorum:',
        7: 'et commisit cum eis praelia multa, et contriti sunt in conspectu eorum, et percussit eos:',
        8: 'et cepit Gazer civitatem, et filias eius, et reversus est in Iudaeam.',
        9: 'Et congregatae sunt gentes, quae sunt in Galaad adversus Israelitas, qui erant in finibus eorum ut tollerent eos: et fugerunt in Datheman munitionem,',
        10: 'et miserunt litteras ad Iudam, et fratres eius, dicentes: Congregatae sunt adversum nos gentes per circuitum, ut nos auferant:',
        11: 'et parant venire, et occupare munitionem, in quam confugimus: et Timotheus est dux exercitus eorum.',
        12: 'Nunc ergo veni, et eripe nos de manibus eorum, quia cecidit multitudo de nobis.',
        13: 'Et omnes fratres nostri, qui erant in locis Tubin, interfecti sunt: et captivas duxerunt uxores eorum, et natos, et spolia, et peremerunt illic fere mille viros.',
        14: 'Et adhuc epistolae legebantur, et ecce alii nuncii venerunt de Galilaea conscissis tunicis, nunciantes secundum verba haec:',
        15: 'dicentes convenisse adversum se a Ptolemaida, et Tyro, et Sidone: et repleta est omnis Galilaea alienigenis, ut nos consumant.',
        16: 'Ut audivit autem Iudas, et populus, sermones istos, convenit ecclesia magna cogitare quid facerent fratribus suis, qui in tribulatione erant, et expugnabantur ab eis.',
        17: 'Dixitque Iudas Simoni fratri suo: Elige tibi viros, et vade, et libera fratres tuos in Galilaea: ego autem, et frater meus Ionathas ibimus in Galaaditim.',
        18: 'Et reliquit Iosephum filium Zachariae, et Azariam duces populi cum residuo exercitu in Iudaea ad custodiam:',
        19: 'et praecepit illis, dicens: Praeestote populo huic: et nolite bellum committere adversum gentes, donec revertamur.',
        20: 'Et partiti sunt Simoni viri tria millia, ut iret in Galilaeam: Iudae autem octo millia in Galaaditim.',
        21: 'Et abiit Simon in Galilaeam, et commisit praelia multa cum gentibus: et contritae sunt gentes a facie eius, et persecutus est eos usque ad portam',
        22: 'Ptolemaidis: et ceciderunt de gentibus fere tria millia virorum, et accepit spolia eorum,',
        23: 'et assumpsit eos, qui erant in Galilaea, et in Arbatis cum uxoribus, et natis, et omnibus quae erant illis, et adduxit in Iudaeam cum laetitia magna.',
        24: 'Et Iudas Machabaeus, et Ionathas frater eius transierunt Iordanem, et abierunt viam trium dierum per desertum.',
        25: 'Et occurrerunt eis Nabuthaei, et susceperunt eos pacifice, et narraverunt eis omnia, quae acciderant fratribus eorum in Galaaditide,',
        26: 'et quia multi ex eis comprehensi sunt in Barasa, et Bosor, et in Alimis, et in Casphor, et Mageth, et Carnaim: hae omnes civitates munitae, et magnae.',
        27: 'Sed et in ceteris civitatibus Galaaditidis tenentur comprehensi, et in crastinum constituerunt admovere exercitum civitatibus his, et comprehendere, et tollere eos in una die.',
        28: 'Et convertit Iudas, et exercitus eius, viam in desertum Bosor repente, et occupavit civitatem: et occidit omnem masculum in ore gladii, et accepit omnia spolia eorum, et succendit eam igne.',
        29: 'Et surrexerunt inde nocte, et ibant usque ad munitionem.',
        30: 'Et factum est diluculo, cum elevassent oculos suos, et ecce populus multus, cuius non erat numerus, portantes scalas, et machinas ut comprehenderent munitionem, et expugnarent eos.',
        31: 'Et vidit Iudas, quia coepit bellum, et clamor belli ascendit ad caelum sicut tuba, et clamor magnus de civitate:',
        32: 'et dixit exercitui suo: Pugnate hodie pro fratribus vestris.',
        33: 'Et venit tribus ordinibus post eos, et exclamaverunt tubis, et clamaverunt in oratione.',
        34: 'Et cognoverunt castra Timothei quia Machabaeus est, et refugerunt a facie eius: et percusserunt eos plaga magna. et ceciderunt ex eis in die illa fere octo millia virorum.',
        35: 'Et divertit Iudas in Maspha, et expugnavit, et cepit eam: et occidit omnem masculum eius, et sumpsit spolia eius, et succendit eam igni.',
        36: 'Inde perrexit, et cepit Casbon, et Mageth, et Bosor, et reliquas civitates Galaaditidis.',
        37: 'Post haec autem verba congregavit Timotheus exercitum alium, et castra posuit contra Raphon trans torrentem.',
        38: 'Et misit Iudas speculari exercitum: et renunciaverunt ei, dicentes: Quia convenerunt ad eum omnes gentes, quae in circuitu nostro sunt, exercitus multus nimis:',
        39: 'et Arabas conduxerunt in auxilium sibi, et castra posuerunt trans torrentem, parati ad te venire in praelium. Et abiit Iudas obviam illis.',
        40: 'Et ait Timotheus principibus exercitus sui: Cum appropinquaverit Iudas, et exercitus eius ad torrentem aquae: si transierit ad nos prior, non poterimus sustinere eum: quia potens poterit adversum nos.',
        41: 'si vero timuerit transire, et posuerit castra extra flumen, transfretamus ad eos, et poterimus adversus illum.',
        42: 'Ut autem appropinquavit Iudas ad torrentem aquae, statuit scribas populi secus torrentem, et mandavit eis, dicens: Neminem hominem relinquatis: sed veniant omnes in praelium.',
        43: 'Et transfretavit ad illos prior, et omnis populus post eum, et contritae sunt omnes gentes a facie eorum, et proiecerunt arma sua, et fugerunt ad phanum, quod erat in Carnaim.',
        44: 'Et occupavit ipsam civitatem, et phanum succendit igne cum omnibus, quae erant in ipso: et oppressa est Carnaim, et non potuit sustinere contra faciem Iudae.',
        45: 'Et congregavit Iudas universos Israelitas, qui erant in Galaaditide, a minimo usque ad maximum, et uxores eorum, et natos, et exercitum magnum valde ut venirent in terram Iuda.',
        46: 'Et venerunt usque Ephron: et haec civitas magna in ingressu posita, munita valde, et non erat declinare ab ea dextera vel sinistra, sed per mediam iter erat.',
        47: 'Et incluserunt se qui erant in civitate, et obstruxerunt portas lapidibus: et misit ad eos Iudas verbis pacificis,',
        48: 'dicens: Transeamus per terram vestram, ut eamus in terram nostram: et nemo vobis nocebit: tantum pedibus transibimus. Et nolebant eis aperire.',
        49: 'Et praecepit Iudas praedicari in castris, ut applicarent unusquisque in quo erat loco.',
        50: 'et applicuerunt se viri virtutis: et oppugnavit civitatem illam tota die, et tota nocte, et tradita est civitas in manu eius:',
        51: 'et peremerunt omnem masculum in ore gladii, et eradicavit eam, et accepit spolia eius, et transivit per totam civitatem super interfectos.',
        52: 'Et transgressi sunt Iordanem in campo magno, contra faciem Bethsan.',
        53: 'Et erat Iudas congregans extremos, et exhortabatur populum per totam viam, donec venirent in terram Iuda:',
        54: 'et ascenderunt in montem Sion cum laetitia, et gaudio, et obtulerunt holocausta, quod nemo ex eis cecidisset donec reverterentur in pace.',
        55: 'Et in diebus, quibus erat Iudas, et Ionathas in terra Galaad, et Simon frater eius in Galilaea contra faciem Ptolemaidis,',
        56: 'audivit Iosephus Zachariae filius, et Azarias princeps virtutis, res bene gestas, et praelia quae facta sunt,',
        57: 'et dixit: Faciamus et ipsi nobis nomen, et eamus pugnare adversus gentes quae in circuitu nostro sunt.',
        58: 'Et praecepit his, qui erant in exercitu suo, et abierunt Iamniam.',
        59: 'Et exivit Gorgias de civitate, et viri eius obviam illis in pugnam.',
        60: 'Et fugati sunt Iosephus, et Azarias usque in fines Iudaeae: et ceciderunt illo die de populo Israel ad duo millia viri, et facta est plaga magna in populo:',
        61: 'quia non audierunt Iudam, et fratres eius, existimantes fortiter se facturos.',
        62: 'Ipsi autem non erant de semine virorum illorum, per quos salus facta est in Israel.',
        63: 'Et viri Iuda magnificati sunt valde in conspectu omnis Israel, et gentium omnium ubi audiebatur nomen eorum.',
        64: 'Et convenerunt ad eos fausta acclamantes.',
        65: 'Et exivit Iudas, et fratres eius, et expugnabant filios Esau in terra, quae ad Austrum est, et percussit Chebron et filias eius: et muros eius, et turres succendit igni in circuitu.',
        66: 'Et movit castra ut iret in terram alienigenarum, et perambulabat Samariam.',
        67: 'In die illa ceciderunt sacerdotes in bello, dum volunt fortiter facere, dum sine consilio exeunt in praelium.',
        68: 'Et declinavit Iudas in Azotum in terram alienigenarum, et diruit aras eorum, et sculptilia deorum ipsorum succendit igni: et cepit spolia civitatum, et reversus est in terram Iuda.',
    },
    6: {
        1: 'Et rex Antiochus perambulabat superiores regiones, et audivit esse civitatem Elymaidem in Perside nobilissimam, et copiosam in argento, et auro,',
        2: 'templumque in ea locuples valde: et illic velamina aurea, et loricae, et scuta, quae reliquit Alexander Philippi rex Macedo, qui regnavit primus in Graecia.',
        3: 'Et venit, et quaerebat capere civitatem, et depraedari eam: et non potuit, quoniam innotuit sermo his, qui erant in civitate:',
        4: 'et insurrexerunt in praelium, et fugit inde, et abiit cum tristitia magna, et reversus est in Babyloniam.',
        5: 'Et venit qui nunciaret ei in Perside, quia fugata sunt castra, quae erant in terra Iuda:',
        6: 'et quia abiit Lysias cum virtute forti in primis, et fugatus est a facie Iudaeorum, et invaluerunt armis, et viribus, et spoliis multis, quae ceperunt de castris, quae exciderunt:',
        7: 'et quia diruerunt abominationem, quam aedificaverat super altare, quod erat in Ierusalem, et sanctificationem, sicut prius, circumdederunt muris excelsis, sed et Bethsuram civitatem suam.',
        8: 'Et factum est ut audivit rex sermones istos, expavit, et commotus est valde: et decidit in lectum, et incidit in languorem prae tristitia, quia non factum est ei sicut cogitabat.',
        9: 'Et erat illic per dies multos: quia renovata est in eo tristitia magna, et arbitratus est se mori.',
        10: 'Et vocavit omnes amicos suos, et dixit illis: Recessit somnus ab oculis meis, et concidi, et corrui corde prae solicitudine:',
        11: 'et dixi in corde meo: In quantam tribulationem deveni, et in quos fluctus tristitiae, in qua nunc sum: qui iucundus eram, et dilectus in potestate mea!',
        12: 'Nunc vero reminiscor malorum, quae feci in Ierusalem, unde et abstuli omnia spolia aurea, et argentea, quae erant in ea, et misi auferre habitantes Iudaeam sine causa.',
        13: 'Cognovi ergo quia propterea invenerunt me mala ista: et ecce pereo tristitia magna in terra aliena.',
        14: 'Et vocavit Philippum, unum de amicis suis, et praeposuit eum super universum regnum suum:',
        15: 'et dedit ei diadema, et stolam suam, et annulum, ut adduceret Antiochum filium suum, et nutriret eum, et regnaret.',
        16: 'Et mortuus est illic Antiochus rex anno centesimo quadragesimo nono.',
        17: 'Et cognovit Lysias, quoniam mortuus est rex, et constituit regnare Antiochum filium eius, quem nutrivit adolescentem: et vocavit nomen eius Eupatorem.',
        18: 'Et hi, qui erant in arce, concluserant Israel in circuitu sanctorum: et quaerebant eis mala semper, et firmamentum Gentium.',
        19: 'Et cogitavit Iudas disperdere eos: et convocavit universum populum, ut obsiderent eos.',
        20: 'Et convenerunt simul, et obsederunt eos anno centesimo quinquagesimo, et fecerunt balistas, et machinas.',
        21: 'Et exierunt quidam ex eis, qui obsidebantur: et adiunxerunt se illis aliqui impii ex Israel,',
        22: 'et abierunt ad regem, et dixerunt: Quousque non facis iudicium, et vindicas fratres nostros?',
        23: 'Nos decrevimus servire patri tuo, et ambulare in praeceptis eius, et obsequi edictis eius:',
        24: 'et filii populi nostri propter hoc alienabant se a nobis, et quicumque inveniebantur ex nobis, interficiebantur, et hereditates nostrae diripiebantur.',
        25: 'Et non ad nos tantum extenderunt manum, sed et in omnes fines nostros.',
        26: 'et ecce applicuerunt hodie ad arcem in Ierusalem occupare eam, et munitionem in Bethsuram munierunt:',
        27: 'et nisi praeveneris eos velocius, maiora, quam haec, facient, et non poteris obtinere eos.',
        28: 'Et iratus est rex, ut haec audivit: et convocavit omnes amicos suos, et principes exercitus sui, et eos, qui super equites erant.',
        29: 'sed et de regnis aliis, et de insulis maritimis venerunt ad eum exercitus conductitii.',
        30: 'Et erat numerus exercitus eius, centum millia peditum, et viginti millia equitum, et elephanti trigintaduo, docti ad praelium.',
        31: 'Et venerunt per Idumaeam, et applicuerunt ad Bethsuram, et pugnaverunt dies multos, et fecerunt machinas et exierunt, et succenderunt eas igne, et pugnaverunt viriliter.',
        32: 'Et recessit Iudas ab arce, et movit castra ad Bethzacharam contra castra regis.',
        33: 'Et surrexit rex ante lucem, et concitavit exercitus in impetum contra viam Bethzacharam: et comparaverunt se exercitus in praelium, et tubis cecinerunt:',
        34: 'et elephantis ostenderunt sanguinem uvae et mori, ad acuendos eos in praelium:',
        35: 'et diviserunt bestias per legiones: et astiterunt singulis elephantis mille viri in loricis concatenatis, et galeae aereae in capitibus eorum: et quingenti equites ordinati unicuique bestiae electi erant.',
        36: 'Hi ante tempus ubicumque erat bestia, ibi erant: et quocumque ibat, ibant, et non discedebant ab ea.',
        37: 'Sed et turres ligneae super eos firmae protegentes super singulas bestias: et super eas machinae: et super singulas viri virtutis triginta duo, qui pugnabant desuper: et Indus magister bestiae.',
        38: 'Et residuum equitatum hinc et inde statuit in duas partes, tubis exercitum commovere, et perurgere constipatos in legionibus eius.',
        39: 'Et ut refulsit sol in clypeos aureos, et aereos, resplenduerunt montes ab eis, et resplenduerunt sicut lampades ignis.',
        40: 'Et distincta est pars exercitus regis per montes excelsos, et alia per loca humilia: et ibant caute et ordinate.',
        41: 'Et commovebantur omnes inhabitantes terram a voce tubae, incessu multitudinis eorum, et collisione armorum: erat enim exercitus magnus valde, et fortis.',
        42: 'Et appropiavit Iudas, et exercitus eius in praelium: et ceciderunt de exercitu regis sexcenti viri.',
        43: 'Et vidit Eleazar filius Saura unam de bestiis loricatam loricis regis: et erat eminens super ceteras bestias. et visum est ei quod in ea esset rex:',
        44: 'et dedit se ut liberaret populum suum, et acquireret sibi nomen aeternum.',
        45: 'Et cucurrit ad eam audacter in medio legionis interficiens a dextris, et a sinistris, et cadebant ab eo huc atque illuc.',
        46: 'Et ivit sub pedes elephantis, et supposuit se ei, et occidit eum: et cecidit in terram super ipsum, et mortuus est illic.',
        47: 'Et videntes virtutem regis, et impetum exercitus eius, diverterunt se ab eis.',
        48: 'Castra autem regis ascenderunt contra eos in Ierusalem, et applicuerunt castra regis ad Iudaeam, et montem Sion.',
        49: 'Et fecit pacem cum his, qui erant in Bethsura: et exierunt de civitate, quia non erant eis ibi alimenta conclusis, quia sabbata erant terrae.',
        50: 'Et comprehendit rex Bethsuram: et constituit illic custodiam servare eam.',
        51: 'Et convertit castra ad locum sanctificationis dies multos: et statuit illic balistas, et machinas, et ignis iacula, et tormenta ad lapides iactandos, et spicula, et scorpios ad mittendas sagittas, et fundibula.',
        52: 'Fecerunt autem et ipsi machinas adversus machinas eorum, et pugnaverunt dies multos.',
        53: 'Escae autem non erant in civitate, eo quod septimus annus esset: et qui remanserant in Iudaea de Gentibus, consumpserant reliquias eorum, quae repositae fuerant.',
        54: 'Et remanserunt in sanctis viri pauci, quoniam obtinuerat eos fames: et dispersi sunt unusquisque in locum suum.',
        55: 'Et audivit Lysias quod Philippus, quem constituerat rex Antiochus, cum adhuc viveret, ut nutriret Antiochum filium suum, et regnaret,',
        56: 'reversus esset a Perside, et Media, et exercitus qui abierat cum ipso, et quia quaerebat suscipere regni negotia:',
        57: 'festinavit ire, et dicere ad regem, et duces exercitus: Deficimus quotidie, et esca nobis modica est, et locus, quem obsidemus, est munitus, et incumbit nobis ordinare de regno.',
        58: 'Nunc itaque demus dextras hominibus istis, et faciamus cum illis pacem, et cum omni gente eorum:',
        59: 'et constituamus illis ut ambulent in legitimis suis sicut prius. propter legitima enim ipsorum, quae despeximus, irati sunt, et fecerunt omnia haec.',
        60: 'Et placuit sermo in conspectu regis, et principum: et misit ad eos pacem facere: et receperunt illam.',
        61: 'Et iuravit illis rex, et principes: et exierunt de munitione.',
        62: 'Et intravit rex montem Sion, et vidit munitionem loci: et rupit citius iuramentum, quod iuravit: et mandavit destruere murum in gyro.',
        63: 'Et discessit festinanter, et reversus est Antiochiam, et invenit Philippum dominantem civitati: et pugnavit adversus eum, et occupavit civitatem.',
    },
    7: {
        1: 'Anno centesimo quinquagesimo primo exiit Demetrius Seleuci filius ab urbe Roma, et ascendit cum paucis viris in civitatem maritimam, et regnavit illic.',
        2: 'Et factum est, ut ingressus est domum regni patrum suorum, comprehendit exercitus Antiochum, et Lysiam, ut adducerent eos ad eum.',
        3: 'Et res ei innotuit: et ait: Nolite mihi ostendere faciem eorum.',
        4: 'Et occidit eos exercitus. Et sedit Demetrius super sedem regni sui:',
        5: 'et venerunt ad eum viri iniqui et impii ex Israel: et Alcimus dux eorum, qui volebat fieri sacerdos.',
        6: 'Et accusaverunt populum apud regem, dicentes: Perdidit Iudas, et fratres eius omnes amicos tuos, et nos disperdidit de terra nostra.',
        7: 'Nunc ergo mitte virum, cui credis, ut eat, et videat exterminium omne, quod fecit nobis, et regionibus regis: et puniat omnes amicos eius, et adiutores eorum.',
        8: 'Et elegit rex ex amicis suis Bacchidem, qui dominabatur trans flumen magnum in regno, et fidelem regi: et misit eum,',
        9: 'ut videret exterminium, quod fecit Iudas: sed et Alcimum impium constituit in sacerdotium, et mandavit ei facere ultionem in filios Israel.',
        10: 'Et surrexerunt, et venerunt cum exercitu magno in terram Iuda: et miserunt nuncios, et locuti sunt ad Iudam, et ad fratres eius verbis pacificis in dolo.',
        11: 'Et non intenderunt sermonibus eorum: viderunt enim quia venerunt cum exercitu magno.',
        12: 'Et convenerunt ad Alcimum, et Bacchidem congregatio scribarum requirere quae iusta sunt:',
        13: 'et primi, Assidaei qui erant in filiis Israel, et exquirebant ab eis pacem.',
        14: 'Dixerunt enim: Homo sacerdos de semine Aaron venit, non decipiet nos:',
        15: 'et locutus est cum eis verba pacifica: et iuravit illis, dicens: Non inferemus vobis malum, neque amicis vestris.',
        16: 'Et crediderunt ei: Et comprehendit ex eis sexaginta viros, et occidit eos in una die secundum verbum, quod scriptum est:',
        17: 'Carnes sanctorum tuorum, et sanguinem ipsorum effuderunt in circuitu Ierusalem, et non erat qui sepeliret.',
        18: 'Et incubuit timor, et tremor in omnem populum: quia dixerunt: Non est veritas, et iudicium in eis: transgressi sunt enim constitutum, et iusiurandum quod iuraverunt.',
        19: 'Et movit Bacchides castra ab Ierusalem, et applicuit in Bethzecham: et misit, et comprehendit multos ex eis, qui a se effugerant, et quosdam de populo mactavit, et in puteum magnum proiecit.',
        20: 'Et commisit regionem Alcimo, et reliquit cum eo auxilium in adiutorium ipsi. Et abiit Bacchides ad regem:',
        21: 'et satis agebat Alcimus pro principatu sacerdotii sui.',
        22: 'et convenerunt ad eum omnes, qui perturbabant populum suum, et obtinuerunt terram Iuda, et fecerunt plagam magnam in Israel.',
        23: 'Et vidit Iudas omnia mala quae fecit Alcimus, et qui cum eo erant, filiis Israel, multo plus quam Gentes.',
        24: 'et exiit in omnes fines Iudaeae in circuitu, et fecit vindictam in viros desertores, et cessaverunt ultra exire in regionem.',
        25: 'Vidit autem Alcimus quod praevaluit Iudas, et qui cum eo erant: et cognovit quia non potest sustinere eos, et regressus est ad regem, et accusavit eos multis criminibus.',
        26: 'Et misit rex Nicanorem, unum ex principibus suis nobilioribus: qui erat inimicitias exercens contra Israel: et mandavit ei evertere populum.',
        27: 'Et venit Nicanor in Ierusalem cum exercitu magno, et misit ad Iudam et ad fratres eius verbis pacificis cum dolo,',
        28: 'dicens: Non sit pugna inter me et vos: veniam cum viris paucis, ut videam facies vestras cum pace.',
        29: 'Et venit ad Iudam, et salutaverunt se invicem pacifice: et hostes parati erant rapere Iudam.',
        30: 'Et innotuit sermo Iudae quoniam cum dolo venerat ad eum: et conterritus est ab eo, et amplius noluit videre faciem eius.',
        31: 'Et cognovit Nicanor quoniam denudatum est consilium eius: et exivit obviam Iudae in pugnam iuxta Capharsalama.',
        32: 'Et ceciderunt de Nicanoris exercitu fere quinque millia viri, et fugerunt in civitatem David.',
        33: 'Et post haec verba ascendit Nicanor in montem Sion: et exierunt de sacerdotibus populi salutare eum in pace, et demonstrare ei holocaustomata, quae offerebantur pro rege.',
        34: 'Et irridens sprevit eos, et polluit: et locutus est superbe,',
        35: 'et iuravit cum ira, dicens: Nisi traditus fuerit Iudas, et exercitus eius in manus meas, continuo cum regressus fuero in pace, succendam domum istam. Et exiit cum ira magna.',
        36: 'et intraverunt sacerdotes, et steterunt ante faciem altaris et templi: et flentes dixerunt:',
        37: 'Tu Domine elegisti domum istam ad invocandum nomen tuum in ea, ut esset domus orationis et obsecrationis populo tuo.',
        38: 'fac vindictam in homine isto, et exercitu eius, et cadant in gladio: memento blasphemias eorum, et ne dederis eis ut permaneant.',
        39: 'Et exiit Nicanor ab Ierusalem, et castra applicuit ad Bethoron: et occurrit illi exercitus Syriae.',
        40: 'Et Iudas applicuit in Adarsa cum tribus millibus viris: et oravit Iudas, et dixit:',
        41: 'Qui missi erant a rege Sennacherib, Domine, quia blasphemaverunt te, exiit angelus, et percussit ex eis centum octogintaquinque millia:',
        42: 'sic contere exercitum istum in conspectu nostro hodie: et sciant ceteri quia male locutus est super sancta tua: et iudica illum secundum malitiam illius.',
        43: 'Et commiserunt exercitus praelium tertiadecima die mensis Adar: et contrita sunt castra Nicanoris, et cecidit ipse primus in praelio.',
        44: 'Ut autem vidit exercitus eius quia cecidisset Nicanor, proiecerunt arma sua, et fugerunt:',
        45: 'et persecuti sunt eos viam unius diei ab Adazer usquequo veniatur in Gazara, et tubis cecinerunt post eos cum significationibus:',
        46: 'et exierunt de omnibus castellis Iudaeae in circuitu, et ventilabant eos cornibus, et convertebantur iterum ad eos, et ceciderunt omnes gladio, et non est relictus ex eis nec unus.',
        47: 'Et acceperunt spolia eorum in praedam: et caput Nicanoris amputaverunt, et dexteram eius, quam extenderat superbe, et attulerunt, et suspenderunt contra Ierusalem.',
        48: 'Et laetatus est populus valde, et egerunt diem illam in laetitia magna.',
        49: 'Et constituit agi omnibus annis diem istam tertiadecima die mensis Adar.',
        50: 'Et siluit terra Iuda dies paucos.',
    },
    8: {
        1: 'Et audivit Iudas nomen Romanorum, quia sunt potentes viribus, et acquiescunt ad omnia, quae postulantur ab eis: et quicumque accesserunt ad eos, statuerunt cum eis amicitias, et quia sunt potentes viribus.',
        2: 'Et audierunt praelia eorum, et virtutes bonas, quas fecerunt in Galatia, quia obtinuerunt eos, et duxerunt sub tributum:',
        3: 'et quanta fecerunt in regione Hispaniae, et quod in potestatem redegerunt metalla argenti et auri, quae illic sunt, et possederunt omnem locum consilio suo, et patientia:',
        4: 'locaque quae longe erant valde ab eis, et reges, qui supervenerant eis ab extremis terrae, contriverunt, et percusserunt eos plaga magna: ceteri autem dant eis tributum omnibus annis.',
        5: 'et Philippum et Persen Ceteorum regem, et ceteros, qui adversum eos arma tulerant, contriverunt in bello, et obtinuerunt eos:',
        6: 'et Antiochum magnum regem Asiae, qui eis pugnam intulerat habens centum viginti elephantos, et equitatum, et currus, et exercitum magnum valde, contritum ab eis.',
        7: 'et quia ceperunt eum vivum, et statuerunt ei ut daret ipse, et qui regnarent post ipsum, tributum magnum, et daret obsides, et constitutum,',
        8: 'et regionem Indorum, et Medos, et Lydos, de optimis regionibus eorum: et acceptas eas ab eis, dederunt Eumeni regi.',
        9: 'et quia qui erant apud Helladam, voluerunt ire, et tollere eos: et innotuit sermo his,',
        10: 'et miserunt ad eos ducem unum, et pugnaverunt contra illos, et ceciderunt ex eis multi, et captivas duxerunt uxores eorum, et filios, et diripuerunt eos, et terram eorum possederunt, et destruxerunt muros eorum, et in servitutem illos redegerunt usque in hunc diem:',
        11: 'et residua regna, et insulas, quae aliquando restiterant illis, exterminaverunt, et in potestatem redegerunt.',
        12: 'Cum amicis autem suis, et qui in ipsis requiem habebant, conservaverunt amicitiam, et obtinuerunt regna, quae erant proxima, et quae erant longe: quia quicumque audiebant nomen eorum, timebant eos:',
        13: 'quibus vero vellent auxilio esse ut regnarent, regnabant: quos autem vellent, regno deturbabant: et exaltati sunt valde.',
        14: 'Et in omnibus istis nemo portabat diadema, nec induebatur purpura, ut magnificaretur in ea.',
        15: 'Et quia curiam fecerunt sibi, et quotidie consulebant trecentos viginti consilium agentes semper de multitudine, ut quae digna sunt, gerant:',
        16: 'et committunt uni homini magistratum suum per singulos annos dominari universae terrae suae, et omnes obediunt uni, et non est invidia, neque zelus inter eos.',
        17: 'Et elegit Iudas Eupolemum, filium Ioannis, filii Iacob, et Iasonem, filium Eleazari, et et misit eos Romam constituere cum illis amicitiam, et societatem:',
        18: 'et ut auferrent ab eis iugum Graecorum, quia viderunt quod in servitutem premerent regnum Israel.',
        19: 'Et abierunt Romam viam multam valde, et introierunt curiam, et dixerunt:',
        20: 'Iudas Machabaeus, et fratres eius, et populus Iudaeorum miserunt nos ad vos statuere vobiscum societatem, et pacem, et conscribere nos socios et amicos vestros.',
        21: 'Et placuit sermo in conspectu eorum.',
        22: 'Et hoc rescriptum est, quod rescripserunt in tabulis aereis, et miserunt in Ierusalem, ut esset apud eos ibi memoriale pacis, et societatis.',
        23: 'BENE SIT ROMANIS, et genti Iudaeorum in mari, et in terra in aeternum: gladiusque et hostis procul sit ab eis.',
        24: 'Quod si institerit bellum Romanis prius, aut omnibus sociis eorum in omni dominatione eorum:',
        25: 'auxilium feret gens Iudaeorum, prout tempus dictaverit, corde pleno:',
        26: 'et praeliantibus non dabunt, neque subministrabunt triticum, arma, pecuniam, naves, sicut placuit Romanis: et custodient mandata eorum, nihil ab eis accipientes.',
        27: 'Similiter autem et si genti Iudaeorum prius acciderit bellum, adiuvabunt Romani ex animo, prout eis tempus permiserit:',
        28: 'et adiuvantibus non dabitur triticum, arma, pecunia, naves, sicut placuit Romanis: et custodient mandata eorum absque dolo.',
        29: 'secundum haec verba constituerunt Romani populo Iudaeorum.',
        30: 'Quod si post haec verba hi aut illi addere, aut demere ad haec aliquid voluerint, facient ex proposito suo: et quaecumque addiderint, vel dempserint, rata erunt.',
        31: 'Sed et de malis, quae Demetrius rex fecit in eos, scripsimus ei, dicentes: Quare gravasti iugum tuum super amicos nostros, et socios Iudaeos?',
        32: 'Si ergo iterum adierint nos, adversum te faciemus illis iudicium, et pugnabimus tecum mari terraque.',
    },
    9: {
        1: 'Interea ut audivit Demetrius quia cecidit Nicanor, et exercitus eius in praelio, apposuit Bacchidem, et Alcimum rursum mittere in Iudaeam, et dextrum cornu cum illis.',
        2: 'Et abierunt viam, quae ducit in Galgala, et castra posuerunt in Masaloth, quae est in Arbellis: et occupaverunt eam, et peremerunt animas hominum multas.',
        3: 'In mense primo anni centesimi et quinquagesimi secundi applicuerunt exercitum ad Ierusalem:',
        4: 'et surrexerunt, et abierunt in Beream viginti millia virorum, et duo millia equitum.',
        5: 'Et Iudas posuerat castra in Laisa, et tria millia viri electi cum eo:',
        6: 'et viderunt multitudinem exercitus quia multi sunt, et timuerunt valde: et multi subtraxerunt se de castris, et non remanserunt ex eis nisi octingenti viri.',
        7: 'Et vidit Iudas quod defluxit exercitus suus, et bellum perurgebat eum, et confractus est corde: quia non habebat tempus congregandi eos, et dissolutus est.',
        8: 'Et dixit his, qui residui erant: Surgamus, et eamus ad adversarios nostros, si poterimus pugnare adversus eos.',
        9: 'Et avertebant eum, dicentes: Non poterimus, sed liberemus animas nostras modo, et revertamur ad fratres nostros, et tunc pugnabimus adversus eos: nos autem pauci sumus.',
        10: 'Et ait Iudas: Absit istam rem facere ut fugiamus ab eis: et si appropiavit tempus nostrum, moriamur in virtute propter fratres nostros, et non inferamus crimen gloriae nostrae.',
        11: 'Et movit exercitus de castris, et steterunt illis obviam: et divisi sunt equites in duas partes, et fundibularii, et sagittarii praeibant exercitum, et primi certaminis omnes potentes.',
        12: 'Bacchides autem erat in dextro cornu, et proximavit legio ex duabus partibus, et clamabant tubis:',
        13: 'exclamaverunt autem et hi, qui erant ex parte Iudae, etiam ipsi, et commota est terra a voce exercituum: et commissum est praelium a mane usque ad vesperam.',
        14: 'Et vidit Iudas, quod firmior est pars exercitus Bacchidis in dextris, et convenerunt cum ipso omnes constantes corde:',
        15: 'et contrita est dextera pars ab eis, et persecutus est eos usque ad montem Azoti.',
        16: 'Et qui in sinistro cornu erant, viderunt quod contritum est dextrum cornu, et secuti sunt post Iudam, et eos, qui cum ipso erant, a tergo:',
        17: 'et ingravatum est praelium, et ceciderunt vulnerati multi ex his, et ex illis.',
        18: 'Et Iudas cecidit, et ceteri fugerunt.',
        19: 'Et Ionathas, et Simon tulerunt Iudam fratrem suum, et sepelierunt eum in sepulchro patrum suorum in civitate Modin.',
        20: 'Et fleverunt eum omnis populus Israel planctu magno, et lugebant dies multos,',
        21: 'et dixerunt: Quomodo cecidit potens, qui salvum faciebat populum Israel!',
        22: 'Et cetera verba bellorum Iudae, et virtutum, quas fecit, et magnitudinis eius, non sunt descripta: multa enim erant valde.',
        23: 'Et factum est: post obitum Iudae emerserunt iniqui in omnibus finibus Israel, et exorti sunt omnes, qui operabantur iniquitatem.',
        24: 'In diebus illis facta est fames magna valde, et tradidit se Bacchidi omnis regio eorum cum ipsis.',
        25: 'Et elegit Bacchides viros impios, et constituit eos dominos regionis:',
        26: 'et exquirebant, et perscrutabantur amicos Iudae, et adducebant eos ad Bacchidem, et vindicabat in illos, et illudebat.',
        27: 'Et facta est tribulatio magna in Israel, qualis non fuit ex die, qua non est visus propheta in Israel.',
        28: 'Et congregati sunt omnes amici Iudae, et dixerunt Ionathae:',
        29: 'Ex quo frater tuus Iudas defunctus est, vir similis ei non est, qui exeat contra inimicos nostros, Bacchidem, et eos, qui inimici sunt gentis nostrae.',
        30: 'Nunc itaque te hodie elegimus esse pro eo nobis in principem, et ducem ad bellandum bellum nostrum.',
        31: 'Et suscepit Ionathas tempore illo principatum, et surrexit loco Iudae fratris sui.',
        32: 'Et cognovit Bacchides, et quaerebat eum occidere.',
        33: 'Et cognovit Ionathas, et Simon frater eius, et omnes, qui cum eo erant: et fugerunt in desertum Thecuae, et consederunt ad aquam lacus Asphar.',
        34: 'Et cognovit Bacchides, et die sabbatorum venit ipse, et omnis exercitus eius trans Iordanem.',
        35: 'Et Ionathas misit fratrem suum ducem populi, et rogavit Nabuthaeos amicos suos, ut commodarent illi apparatum suum, qui erat copiosus.',
        36: 'Et exierunt filii Iambri ex Madaba, et comprehenderunt Ioannem, et omnia, quae habebat, et abierunt habentes ea.',
        37: 'Post haec verba, renunciatum est Ionathae, et Simoni fratri eius, quia filii Iambri faciunt nuptias magnas, et ducunt sponsam ex Madaba filiam unius de magnis principibus Chanaan cum ambitione magna.',
        38: 'Et recordati sunt sanguinis Ioannis fratris sui: et ascenderunt, et absconderunt se sub tegumento montis.',
        39: 'Et elevaverunt oculos suos, et viderunt: et ecce tumultus, et apparatus multus: et sponsus processit, et amici eius, et fratres eius obviam illis cum tympanis, et musicis, et armis multis.',
        40: 'Et surrexerunt ad eos ex insidiis, et occiderunt eos, et ceciderunt vulnerati multi, et residui fugerunt in montes: et acceperunt omnia spolia eorum:',
        41: 'et conversae sunt nuptiae in luctum, et vox musicorum ipsorum in lamentum.',
        42: 'Et vindicaverunt vindictam sanguinis fratris sui: et reversi sunt ad ripam Iordanis.',
        43: 'Et audivit Bacchides, et venit die sabbatorum usque ad oram Iordanis in virtute magna.',
        44: 'Et dixit ad suos Ionathas: Surgamus, et pugnemus contra inimicos nostros: non est enim hodie sicut heri, et nudiustertius.',
        45: 'ecce enim bellum ex adverso, aqua vero Iordanis hinc et inde, et ripae, et paludes, et saltus: et non est locus divertendi.',
        46: 'Nunc ergo clamate in caelum, ut liberemini de manu inimicorum vestrorum. Et commissum est bellum.',
        47: 'Et extendit Ionathas manum suam percutere Bacchidem, et divertit ab eo retro:',
        48: 'et desiliit Ionathas, et qui cum eo erant in Iordanem, et transnataverunt ad eos Iordanem.',
        49: 'et ceciderunt de parte Bacchidis die illa mille viri: et reversi sunt in Ierusalem,',
        50: 'et aedificaverunt civitates munitas in Iudaea, munitionem, quae erat in Iericho, et in Ammaum, et in Bethoron, et in Bethel, et Thamnata, et Phara, et Thopo muris excelsis, et portis, et seris.',
        51: 'Et posuit custodiam in eis, ut inimicitias exercerent in Israel:',
        52: 'et munivit civitatem Bethsuram, et Gazaram, et arcem, et posuit in eis auxilia, et apparatum escarum:',
        53: 'et accepit filios principum regionis obsides, et posuit eos in arce in Ierusalem in custodiam.',
        54: 'Et anno centesimo quinquagesimo tertio, mense secundo, praecepit Alcimus destrui muros domus sanctae interioris, et destrui opera prophetarum: et coepit destruere.',
        55: 'In tempore illo percussus est Alcimus: et impedita sunt opera illius, et occlusum est os eius, et dissolutus est paralysi, nec ultra potuit loqui verbum, et mandare de domo sua.',
        56: 'Et mortuus est Alcimus in tempore illo cum tormento magno.',
        57: 'Et vidit Bacchides quoniam mortuus est Alcimus: et reversus est ad regem. Et siluit terra annis duobus.',
        58: 'Et cogitaverunt omnes iniqui dicentes: Ecce Ionathas, et qui cum eo sunt, in silentio habitant confidenter: nunc ergo adducamus Bacchidem, et comprehendet eos omnes una nocte.',
        59: 'Et abierunt, et consilium ei dederunt.',
        60: 'Et surrexit ut veniret cum exercitu multo: et misit occulte epistolas sociis suis, qui erant in Iudaea, ut comprehenderent Ionathan, et eos, qui cum eo erant: sed non potuerunt, quia innotuit eis consilium eorum.',
        61: 'Et apprehendit de viris regionis, qui principes erant malitiae, quinquaginta viros, et occidit eos:',
        62: 'et secessit Ionathas, et Simon, et qui cum eo erant in Bethbessen, quae est in deserto: et extruxit diruta eius, et firmaverunt eam.',
        63: 'Et cognovit Bacchides, et congregavit universam multitudinem suam: et his, qui de Iudaea erant, denunciavit.',
        64: 'Et venit, et castra posuit desuper Bethbessen: et oppugnavit eam dies multos, et fecit machinas.',
        65: 'Et reliquit Ionathas Simonem fratrem suum in civitate, et exiit in regionem, et venit cum numero,',
        66: 'et percussit Odaren, et fratres eius, et filios Phaseron in tabernaculis ipsorum: et coepit caedere, et crescere in virtutibus.',
        67: 'Simon vero, et qui cum ipso erant, exierunt de civitate, et succenderunt machinas,',
        68: 'et pugnaverunt contra Bacchidem, et contritus est ab eis: et afflixerunt eum valde, quoniam consilium eius, et congressus eius erat inanis.',
        69: 'Et iratus contra viros iniquos, qui ei consilium dederant ut veniret in regionem ipsorum, multos ex eis occidit: ipse autem cogitavit cum reliquis abire in regionem suam.',
        70: 'Et cognovit Ionathas: et misit ad eum legatos componere pacem cum ipso, et reddere ei captivitatem.',
        71: 'Et libenter accepit, et fecit secundum verba eius, et iuravit se nihil facturum ei mali omnibus diebus vitae eius.',
        72: 'Et reddidit ei captivitatem, quam prius erat praedatus de terra Iuda: et conversus abiit in terram suam, et non apposuit amplius venire in fines eius:',
        73: 'Et cessavit gladius ex Israel: et habitavit Ionathas in Machmas, et coepit Ionathas ibi iudicare populum, et exterminavit impios ex Israel.',
    },
    10: {
        1: 'Et anno centesimo sexagesimo ascendit Alexander Antiochi filius, qui cognominatus est Nobilis: et occupavit Ptolemaidam: et receperunt eum, et regnavit illic.',
        2: 'Et audivit Demetrius rex, et congregavit exercitum copiosum valde, et exivit obviam illi in praelium.',
        3: 'Et misit Demetrius epistolam ad Ionathan verbis pacificis, ut magnificaret eum.',
        4: 'Dixit enim: Anticipemus facere pacem cum eo, priusquam faciat cum Alexandro adversum nos.',
        5: 'recordabitur enim omnium malorum, quae fecimus in eum, et in fratrem eius, et in gentem eius.',
        6: 'Et dedit ei potestatem congregandi exercitum, et fabricare arma, et esse ipsum socium eius: et obsides, qui erant in arce, iussit tradi ei.',
        7: 'Et venit Ionathas in Ierusalem, et legit epistolas in auditu omnis populi, et eorum, qui in arce erant.',
        8: 'Et timuerunt timore magno, quoniam audierunt quod dedit ei rex potestatem congregandi exercitum.',
        9: 'Et traditi sunt Ionathae obsides, et reddidit eos parentibus suis:',
        10: 'et habitavit Ionathas in Ierusalem, et coepit aedificare, et innovare civitatem.',
        11: 'Et dixit facientibus opera ut extruerent muros, et montem Sion in circuitu lapidibus quadratis ad munitionem: et ita fecerunt.',
        12: 'Et fugerunt alienigenae, qui erant in munitionibus, quas Bacchides aedificaverat:',
        13: 'et reliquit unusquisque locum suum, et abiit in terram suam:',
        14: 'tantum in Bethsura remanserunt aliqui ex his, qui reliquerant legem, et praecepta Dei. erat enim haec eis ad refugium.',
        15: 'Et audivit Alexander rex promissa, quae promisit Demetrius Ionathae: et narraverunt ei praelia, et virtutes, quas ipse fecit, et fratres eius, et labores, quos laboraverunt.',
        16: 'et ait: Numquid inveniemus aliquem virum talem? et nunc faciemus eum amicum, et socium nostrum.',
        17: 'Et scripsit epistolam, et misit ei secundum haec verba, dicens:',
        18: 'REX Alexander fratri Ionathae salutem.',
        19: 'Audivimus de te quod vir potens sis viribus, et aptus ut sis amicus noster:',
        20: 'et nunc constituimus te hodie summum sacerdotem gentis tuae, et ut amicus voceris regis, (et misit ei purpuram, et coronam auream) et quae nostra sunt sentias nobiscum, et conserves amicitias ad nos.',
        21: 'Et induit se Ionathas stola sancta septimo mense, anno centesimo sexagesimo in die sollemni scenophegiae: et congregavit exercitum, et fecit arma copiosa.',
        22: 'Et audivit Demetrius verba ista, et contristatus est nimis, et ait:',
        23: 'Quid hoc fecimus, quod praeoccupavit nos Alexander apprehendere amicitiam Iudaeorum ad munimen sui?',
        24: 'Scribam et ego illis verba deprecatoria, et dignitates, et dona: ut sint mecum in adiutorium.',
        25: 'Et scripsit eis in haec verba: Rex Demetrius genti Iudaeorum salutem:',
        26: 'Quoniam servastis ad nos pactum, et mansistis in amicitia nostra, et non accessistis ad inimicos nostros, audivimus, et gavisi sumus.',
        27: 'Et nunc perseverate adhuc conservare ad nos fidem, et retribuemus vobis bona pro his, quae fecistis nobiscum:',
        28: 'et remittemus vobis praestationes multas, et dabimus vobis donationes.',
        29: 'Et nunc absolvo vos, et omnes Iudaeos a tributis, et pretia salis indulgeo, et coronas remitto, et tertias seminis:',
        30: 'et dimidiam partem fructus ligni, quod est portionis meae, relinquo vobis ex hodierno die, et deinceps, ne accipiatur a terra Iuda, et a tribus civitatibus, quae additae sunt illi ex Samaria, et Galilaea ex hodierna die et in totum tempus:',
        31: 'et Ierusalem sit sancta, et libera cum finibus suis: et decimae, et tributa ipsius sint.',
        32: 'Remitto etiam potestatem arcis, quae est in Ierusalem: et do eam summo sacerdoti, ut constituat in ea viros quoscumque ipse elegerit, qui custodiant eam.',
        33: 'Et omnem animam Iudaeorum, quae captiva est a terra Iuda in omni regno meo, relinquo liberam gratis, ut omnes a tributis solvantur, etiam pecorum suorum.',
        34: 'Et omnes dies sollemnes, et sabbata, et neomeniae, et dies decreti, et tres dies ante diem sollemnem, et tres dies post diem sollemnem sint omnes immunitatis et remissionis omnibus Iudaeis, qui sunt in regno meo:',
        35: 'et nemo habebit potestatem agere aliquid, et movere negotia adversus aliquem illorum in omni causa.',
        36: 'Et ascribantur ex Iudaeis in exercitu regis ad triginta millia virorum: et dabuntur illis copiae ut oportet omnibus exercitibus regis, et ex eis ordinabuntur qui sint in munitionibus regis magni:',
        37: 'et ex his constituentur super negotia regni, quae aguntur ex fide, et principes sint ex eis, et ambulent in legibus suis, sicut praecepit rex in terra Iuda.',
        38: 'Et tres civitates, quae additae sunt Iudaeae ex regione Samariae, cum Iudaea reputentur: ut sint sub uno, et non obediant alii potestati, nisi summi sacerdotis:',
        39: 'Ptolemaida, et confines eius, quas dedi donum sanctis, qui sunt in Ierusalem ad necessarios sumptus sanctorum.',
        40: 'Et ego dabo singulis annis quindecim millia siclorum argenti de rationibus regis, quae me contingunt:',
        41: 'et omne, quod reliquum fuerit, quod non reddiderant qui super negotia erant annis prioribus, ex hoc dabunt in opera domus.',
        42: 'Et super haec quinque millia siclorum argenti, quae accipiebant de sanctorum ratione per singulos annos: et haec ad sacerdotes pertineant, qui ministerio funguntur.',
        43: 'Et quicumque confugerint in templum, quod est Ierosolymis, et in omnibus finibus eius, obnoxii regi in omni negotio dimittantur, et universa, quae sunt eis in regno meo, libera habeant.',
        44: 'Et ad aedificanda vel restauranda opera sanctorum, sumptus dabuntur de ratione regis:',
        45: 'et ad extruendos muros Ierusalem, et communiendos in circuitu, sumptus dabuntur de ratione regis, et ad construendos muros in Iudaea.',
        46: 'Ut audivit autem Ionathas, et populus sermones istos, non crediderunt eis, nec receperunt eos: quia recordati sunt malitiae magnae, quam fecerat in Israel, et tribulaverat eos valde.',
        47: 'Et complacuit eis in Alexandrum, quia ipse fuerat eis princeps sermonum pacis, et ipsi auxilium ferebant omnibus diebus.',
        48: 'Et congregavit rex Alexander exercitum magnum, et admovit castra contra Demetrium.',
        49: 'Et commiserunt praelium duo reges, et fugit exercitus Demetrii, et insecutus est eum Alexander, et incubuit super eos.',
        50: 'Et invaluit praelium nimis, donec occidit sol: et cecidit Demetrius in die illa.',
        51: 'Et misit Alexander ad Ptolemaeum regem Aegypti legatos secundum haec verba, dicens:',
        52: 'QUONIAM regressus sum in regnum meum, et sedi in sede patrum meorum, et obtinui principatum, et contrivi Demetrium, et possedi regionem nostram,',
        53: 'et commisi pugnam cum eo, et contritus est ipse, et castra eius a nobis, et sedemus in sede regni eius:',
        54: 'et nunc statuamus ad invicem amicitiam: et da mihi filiam tuam uxorem, et ego ero gener tuus, et dabo tibi dona, et ipsi dignitatem.',
        55: 'Et respondit rex Ptolemaeus, dicens: FELIX dies, in qua reversus es ad terram patrum tuorum, et sedisti in sede regni eorum.',
        56: 'Et nunc faciam tibi quod scripsisti: sed occurre mihi Ptolemaidam, ut videamus invicem nos, et spondeam tibi sicut dixisti.',
        57: 'Et exivit Ptolemaeus de Aegypto, ipse et Cleopatra filia eius, et venit Ptolemaidam anno centesimo sexagesimo secundo.',
        58: 'Et occurrit ei Alexander rex, et dedit ei Cleopatram filiam suam: et fecit nuptias eius Ptolemaidae, sicut reges, in magna gloria.',
        59: 'Et scripsit rex Alexander Ionathae, ut veniret obviam sibi.',
        60: 'Et abiit cum gloria Ptolemaidam, et occurrit ibi duobus regibus, et dedit illis argentum multum, et aurum, et dona: et invenit gratiam in conspectu eorum.',
        61: 'Et convenerunt adversus eum viri pestilentes ex Israel, viri iniqui interpellantes adversus eum: et non intendit ad eos rex.',
        62: 'Et iussit spoliari Ionathan vestibus suis, et indui eum purpura: et ita fecerunt. Et collocavit eum rex sedere secum.',
        63: 'Dixitque principibus suis: Exite cum eo in medium civitatis, et praedicate, ut nemo adversus eum interpellet de ullo negotio, nec quisquam ei molestus sit de ulla ratione.',
        64: 'Et factum est, ut viderunt qui interpellabant gloriam eius, quae praedicabatur, et opertum eum purpura, fugerunt omnes:',
        65: 'et magnificavit eum rex, et scripsit eum inter primos amicos, et posuit eum ducem, et participem principatus.',
        66: 'Et reversus est Ionathas in Ierusalem cum pace, et laetitia.',
        67: 'In anno centesimo sexagesimoquinto venit Demetrius filius Demetrii a Creta in terram patrum suorum.',
        68: 'Et audivit Alexander rex, et contristatus est valde, et reversus est Antiochum.',
        69: 'Et constituit Demetrius rex Apollonium ducem, qui praeerat Coelesyriae: et congregavit exercitum magnum, et accessit ad Iamniam: et misit ad Ionathan summum sacerdotem,',
        70: 'dicens: Tu solus resistis nobis: ego autem factus sum in derisum, et in opprobrium, propterea quia tu potestatem adversum nos exerces in montibus.',
        71: 'Nunc ergo si confidis in virtutibus tuis, descende ad nos in campum, et comparemus illic invicem: quia mecum est virtus bellorum.',
        72: 'Interroga, et disce quis sum ego, et ceteri, qui auxilio sunt mihi, qui et dicunt quia non potest stare pes vester ante faciem nostram, quia bis in fugam conversi sunt patres tui in terra sua:',
        73: 'et nunc quomodo poteris sustinere equitatum et exercitum tantum in campo, ubi non est lapis, neque saxum, neque locus fugiendi?',
        74: 'Ut audivit autem Ionathas sermones Apollonii, motus est animo: et elegit decem millia virorum, et exiit ab Ierusalem, et occurrit ei Simon frater eius in adiutorium:',
        75: 'et applicuerunt castra in Ioppen, et exclusit eum a civitate: quia custodia Apollonii Ioppe erat, et oppugnavit eam.',
        76: 'Et exterriti qui erant in civitate, aperuerunt ei, et obtinuit Ionathas Ioppen.',
        77: 'Et audivit Apollonius, et admovit tria millia equitum, et exercitum multum.',
        78: 'Et abiit Azotum tamquam iter faciens, et statim exiit in campum, eo quod haberet multitudinem equitum, et confideret in eis. Et insecutus est eum Ionathas in Azotum, et commiserunt praelium.',
        79: 'Et reliquit Apollonius in castris mille equites post eos occulte.',
        80: 'Et cognovit Ionathas quoniam insidiae sunt post se, et circuierunt castra eius, et iecerunt iacula in populum a mane usque ad vesperam.',
        81: 'Populus autem stabat, sicut praeceperat Ionathas: et laboraverunt equi eorum.',
        82: 'Et eiecit Simon exercitum suum, et commisit contra legionem. equites enim fatigati erant: et contriti sunt ab eo, et fugerunt.',
        83: 'Et qui dispersi sunt per campum, fugerunt in Azotum, et intraverunt in Bethdagon idolum suum, ut ibi se liberarent.',
        84: 'Et succendit Ionathas Azotum, et civitates, quae erant in circuitu eius, et accepit spolia eorum, et templum Dagon: et omnes, qui fugerunt in illud, succendit igne.',
        85: 'Et fuerunt qui ceciderunt gladio cum his, qui succensi sunt, fere octo millia virorum.',
        86: 'Et movit inde Ionathas castra, et applicuit ea Ascalonem: et exierunt de civitate obviam illi in magna gloria.',
        87: 'Et reversus est Ionathas in Ierusalem cum suis, habentibus spolia multa.',
        88: 'Et factum est: ut audivit Alexander rex sermones istos, addidit adhuc glorificare Ionathan.',
        89: 'Et misit ei fibulam auream, sicut consuetudo est dari cognatis regum. Et dedit ei Accaron, et omnes fines eius in possessionem.',
    },
    11: {
        1: 'Et rex Aegypti congregavit exercitum, sicut arena, quae est circa oram maris, et naves multas: et quaerebat obtinere regnum Alexandri dolo, et addere illud regno suo.',
        2: 'Et exiit in Syriam verbis pacificis, et aperiebant ei civitates, et occurrebant ei: quia mandaverat Alexander rex exire ei obviam, eo quod socer suus esset.',
        3: 'Cum autem introiret civitatem Ptolemaeus, ponebat custodias militum in singulis civitatibus.',
        4: 'Et ut appropiavit Azoto, ostenderunt ei templum Dagon succensum igne, et Azotum, et cetera eius demolita, et corpora proiecta, et eorum, qui caesi erant in bello, tumulos quos fecerant secus viam.',
        5: 'Et narraverunt regi quia haec fecit Ionathas, ut invidiam facerent ei: et tacuit rex.',
        6: 'Et occurrit Ionathas regi in Ioppen cum gloria, et invicem se salutaverunt, et dormierunt illic.',
        7: 'Et abiit Ionathas cum rege usque ad fluvium, qui vocatur Eleutherus: et reversus est in Ierusalem.',
        8: 'Rex autem Ptolemaeus obtinuit dominium civitatum usque Seleuciam maritimam, et cogitabat in Alexandrum consilia mala.',
        9: 'Et misit legatos ad Demetrium, dicens: VENI, componamus inter nos pactum, et dabo tibi filiam meam, quam habet Alexander, et regnabis in regno patris tui.',
        10: 'poenitet enim me quod dederim illi filiam meam: quaesivit enim me occidere.',
        11: 'Et vituperavit eum, propterea quod concupierat regnum eius.',
        12: 'Et abstulit filiam suam, et dedit eam Demetrio, et alienavit se ab Alexandro, et manifestae sunt inimicitiae eius.',
        13: 'Et intravit Ptolemaeus Antiochiam, et imposuit duo diademata capiti suo, Aegypti, et Asiae.',
        14: 'Alexander autem rex erat in Cilicia illis temporibus: quia rebellabant qui erant in locis illis.',
        15: 'Et audivit Alexander, et venit ad eum in bellum: et produxit Ptolemaeus rex exercitum, et occurrit ei in manu valida, et fugavit eum.',
        16: 'Et fugit Alexander in Arabiam, ut ibi protegeretur: rex autem Ptolemaeus exaltatus est.',
        17: 'Et abstulit Zabdiel Arabs caput Alexandri; et misit Ptolemaeo.',
        18: 'Et rex Ptolemaeus mortuus est in die tertia: et qui erant in munitionibus, perierunt ab his, qui erant intra castra.',
        19: 'Et regnavit Demetrius anno centesimo sexagesimo septimo.',
        20: 'In diebus illis congregavit Ionathas eos, qui erant in Iudaea, ut expugnarent arcem, quae est in Ierusalem: et fecerunt contra eam machinas multas.',
        21: 'Et abierunt quidam qui oderant gentem suam viri iniqui ad regem Demetrium, et renunciaverunt ei quod Ionathas obsideret arcem.',
        22: 'Et ut audivit, iratus est: et statim venit ad Ptolemaidam, et scripsit Ionathae ne obsideret arcem, sed occurreret sibi ad colloquium festinato.',
        23: 'Ut audivit autem Ionathas, iussit obsidere: et elegit de senioribus Israel, et de sacerdotibus, et dedit se periculo.',
        24: 'Et accepit aurum, et argentum, et vestem, et alia xenia multa, et abiit ad regem Ptolemaidam, et invenit gratiam in conspectu eius.',
        25: 'Et interpellabant adversus eum quidam iniqui ex gente sua.',
        26: 'Et fecit ei rex sicut fecerant ei, qui ante eum fuerant: et exaltavit eum in conspectu omnium amicorum suorum,',
        27: 'et statuit ei principatum sacerdotii, et quaecumque alia habuit prius pretiosa, et fecit eum principem amicorum.',
        28: 'Et postulavit Ionathas a rege ut immunem faceret Iudaeam, et tres toparchias, hoc est Samariam, et confines eius: et promisit ei talenta trecenta.',
        29: 'Et consensit rex: et scripsit Ionathae epistolas de his omnibus, hunc modum continentes:',
        30: 'REX Demetrius fratri Ionathae salutem, et genti Iudaeorum.',
        31: 'Exemplum epistolae, quam scripsimus Lastheni parenti nostro de vobis, misimus ad vos ut sciretis:',
        32: 'Rex Demetrius Lastheni parenti salutem.',
        33: 'Genti Iudaeorum amicis nostris, et conservantibus quae iusta sunt apud nos, decrevimus benefacere propter benignitatem ipsorum, quam erga nos habent.',
        34: 'Statuimus ergo illis omnes fines Iudaeae, et tres civitates, Lydan, et Ramathan, quae additae sunt Iudaeae ex Samaria, et omnes confines earum sequestrari omnibus sacrificantibus in Ierosolymis pro his, quae ab eis prius accipiebat rex per singulos annos, et pro fructibus terrae, et pomorum.',
        35: 'Et alia, quae ad nos pertinebant decimarum, et tributorum ex hoc tempore remittimus eis: et areas salinarum, et coronas, quae nobis deferebantur,',
        36: 'omnia ipsis concedimus: et nihil horum irritum erit ex hoc, et in omne tempus.',
        37: 'Nunc ergo curate facere horum exemplum, et detur Ionathae, et ponatur in monte sancto, in loco celebri.',
        38: 'Et videns Demetrius rex quod siluit terra in conspectu suo, et nihil ei resistit, dimisit totum exercitum suum, unumquemque in locum suum, excepto peregrino exercitu, quem contraxit ab insulis Gentium: et inimici erant ei omnes exercitus patrum eius.',
        39: 'Tryphon autem erat quidam partium Alexandri prius: et vidit quoniam omnis exercitus murmurabat contra Demetrium, et ivit ad Emalchuel Arabem, qui nutriebat Antiochum filium Alexandri:',
        40: 'et assidebat ei, ut traderet eum ipsi, ut regnaret loco patris sui: et enunciavit ei quanta fecit Demetrius, et inimicitias exercituum eius adversus illum. Et mansit ibi diebus multis.',
        41: 'Et misit Ionathas ad Demetrium regem, ut eiiceret eos, qui in arce erant in Ierusalem, et qui in praesidiis erant: quia impugnabant Israel.',
        42: 'Et misit Demetrius ad Ionathan, dicens: Non haec tantum faciam tibi, et genti tuae, sed gloria illustrabo te, et gentem tuam cum fuerit opportunum.',
        43: 'Nunc ergo recte feceris, si miseris in auxilium mihi viros: quia discessit omnis exercitus meus.',
        44: 'Et misit ei Ionathas tria millia virorum fortium Antiochiam: et venerunt ad regem, et delectatus est rex in adventu eorum.',
        45: 'Et convenerunt qui erant de civitate, centum viginti millia virorum, et volebant interficere regem.',
        46: 'Et fugit rex in aulam: et occupaverunt qui erant de civitate, itinera civitatis, et coeperunt pugnare.',
        47: 'Et vocavit rex Iudaeos in auxilium, et convenerunt omnes simul ad eum, et dispersi sunt omnes per civitatem:',
        48: 'et occiderunt in illa die centum millia hominum, et succenderunt civitatem, et ceperunt spolia multa in die illa, et liberaverunt regem.',
        49: 'Et viderunt qui erant de civitate, quod obtinuissent Iudaei civitatem sicut volebant: et infirmati sunt mente sua, et clamaverunt ad regem cum precibus, dicentes:',
        50: 'Da nobis dextras, et cessent Iudaei oppugnare nos, et civitatem.',
        51: 'Et proiecerunt arma sua, et fecerunt pacem, et glorificati sunt Iudaei in conspectu regis, et in conspectu omnium, qui erant in regno eius, et nominati sunt in regno: et regressi sunt in Ierusalem habentes spolia multa.',
        52: 'Et sedit Demetrius rex in sede regni sui: et siluit terra in conspectu eius.',
        53: 'Et mentitus est omnia quaecumque dixit, et abalienavit se a Ionatha, et non retribuit ei secundum beneficia, quae sibi tribuerat, et vexabat eum valde.',
        54: 'Post haec autem reversus est Tryphon, et Antiochus cum eo puer adolescens, et regnavit, et imposuit sibi diadema.',
        55: 'Et congregati sunt ad eum omnes exercitus, quos disperserat Demetrius, et pugnaverunt contra eum: et fugit, et terga vertit.',
        56: 'Et accepit Tryphon bestias, et obtinuit Antiochiam:',
        57: 'et scripsit Antiochus adolescens Ionathae, dicens: Constituo tibi sacerdotium, et constituo te super quattuor civitates, ut sis de amicis regis.',
        58: 'Et misit illi vasa aurea in ministerium, et dedit ei potestatem bibendi in auro, et esse in purpura, et habere fibulam auream:',
        59: 'et Simonem fratrem eius constituit ducem a terminis Tyri usque ad fines Aegypti.',
        60: 'Et exiit Ionathas, et perambulabat trans flumen civitates: et congregatus est ad eum omnis exercitus Syriae in auxilium, et venit Ascalonem, et occurrerunt ei honorifice de civitate.',
        61: 'Et abiit inde Gazam: et concluserunt se qui erant Gazae: et obsedit eam, et succendit quae erant in circuitu civitatis, et praedatus est ea.',
        62: 'Et rogaverunt Gazenses Ionathan, et dedit illis dexteram: et accepit filios eorum obsides, et misit illos in Ierusalem: et perambulavit regionem usque Damascum.',
        63: 'Et audivit Ionathas quod praevaricati sunt principes Demetrii in Cades, quae est in Galilaea, cum exercitu multo, volentes eum removere a negotio regni:',
        64: 'et occurrit illis: fratrem autem suum Simonem reliquit intra provinciam.',
        65: 'Et applicuit Simon ad Bethsuram, et expugnabat eam diebus multis, et conclusit eos.',
        66: 'Et postulaverunt ab eo dextras accipere, et dedit illis: et eiecit eos inde, et cepit civitatem, et posuit in ea praesidium.',
        67: 'Et Ionathas, et castra eius applicuerunt ad aquam Genesar, et ante lucem vigilaverunt in campo Asor.',
        68: 'et ecce castra alienigenarum occurrebant in campo, et tendebant ei insidias in montibus: ipse autem occurrit ex adverso.',
        69: 'Insidiae vero exurrexerunt de locis suis, et commiserunt praelium.',
        70: 'Et fugerunt qui erant ex parte Ionathae omnes, et nemo relictus est ex eis, nisi Mathathias filius Absolomi, et Iudas filius Calphi, princeps militiae exercitus.',
        71: 'Et scidit Ionathas vestimenta sua, et posuit terram in capite suo, et oravit.',
        72: 'Et reversus est Ionathas ad eos in praelium, et convertit eos in fugam, et pugnaverunt.',
        73: 'Et viderunt qui fugiebant partis illius, et reversi sunt ad eum, et insequebantur cum eo omnes usque Cades ad castra sua, et pervenerunt usque illuc.',
        74: 'et ceciderunt de alienigenis in die illa tria millia virorum: et reversus est Ionathas in Ierusalem.',
    },
    12: {
        1: 'Et vidit Ionathas quia tempus eum iuvat, et elegit viros, et misit eos Romam statuere, et renovare cum eis amicitiam:',
        2: 'et ad Spartiatas, et ad alia loca misit epistolas secundum eamdem formam:',
        3: 'et abierunt Romam, et intraverunt curiam, et dixerunt: Ionathas summus sacerdos, et gens Iudaeorum miserunt nos, ut renovaremus amicitiam, et societatem secundum pristinum.',
        4: 'Et dederunt illis epistolas ad ipsos per loca, ut deducerent eos in terram Iuda cum pace.',
        5: 'Et hoc est exemplum epistolarum, quas scripsit Ionathas Spartiatis:',
        6: 'IONATHAS summus sacerdos, et seniores gentis, et sacerdotes, et reliquus populus Iudaeorum Spartiatis fratribus salutem.',
        7: 'Iampridem missae erant epistolae ad Oniam summum sacerdotem a Dario, qui regnabat apud vos, quoniam estis fratres nostri, sicut scriptum continet, quod subiectum est.',
        8: 'Et suscepit Onias virum, qui missus fuerat, cum honore: et accepit epistolas, in quibus significabatur de societate, et amicitia.',
        9: 'Nos, cum nullo horum indigeremus, habentes solatio sanctos libros, qui sunt in manibus nostris,',
        10: 'maluimus mittere ad vos renovare fraternitatem, et amicitiam, ne forte alieni efficiamur a vobis: multa enim tempora transierunt, ex quo misistis ad nos.',
        11: 'Nos ergo in omni tempore sine intermissione in diebus sollemnibus, et ceteris, quibus oportet, memores sumus vestri in sacrificiis, quae offerimus, et in observationibus, sicut fas est, et decet meminisse fratrum.',
        12: 'Laetamur itaque de gloria vestra.',
        13: 'Nos autem circumdederunt multae tribulationes, et multa praelia, et impugnaverunt nos reges qui sunt in circuitu nostro.',
        14: 'Noluimus ergo vobis molesti esse, neque ceteris sociis et amicis nostris in his praeliis.',
        15: 'habuimus enim de caelo auxilium, et liberati sumus nos, et humiliati sunt inimici nostri.',
        16: 'Elegimus itaque Numenium Antiochi filium, et Antipatrem Iasonis filium, et misimus ad Romanos renovare cum eis amicitiam, et societatem pristinam.',
        17: 'Mandavimus itaque eis ut veniant etiam ad vos, et salutent vos: et reddant vobis epistolas nostras de innovatione fraternitatis nostrae.',
        18: 'Et nunc benefacietis respondentes nobis ad haec.',
        19: 'Et hoc est rescriptum epistolarum, quod miserat Oniares,',
        20: 'rex Spartiatarum: Oniares Ionathae sacerdoti magno salutem.',
        21: 'Inventum est in scriptura de Spartiatis, et Iudaeis, quoniam sunt fratres, et quod sunt de genere Abraham.',
        22: 'Et nunc ex quo haec cognovimus, benefacitis scribentes nobis de pace vestra:',
        23: 'Sed et nos rescripsimus vobis: Pecora nostra et possessiones nostrae, vestrae sunt: et vestrae, nostrae: mandavimus itaque haec nunciari vobis.',
        24: 'Et audivit Ionathas quoniam regressi sunt principes Demetrii cum exercitu multo supra quam prius, pugnare adversus eum.',
        25: 'et exiit ab Ierusalem, et occurrit eis in Amathite regione: non enim dederat eis spatium ut ingrederentur regionem eius.',
        26: 'Et misit speculatores in castra eorum: et reversi renunciaverunt quod constituunt supervenire illis nocte.',
        27: 'Cum occidisset autem sol, praecepit Ionathas suis vigilare, et esse in armis paratos ad pugnam tota nocte, et posuit custodes per circuitum castrorum.',
        28: 'Et audierunt adversarii quod paratus est Ionathas cum suis in bello: et timuerunt, et formidaverunt in corde suo: et accenderunt focos in castris suis.',
        29: 'Ionathas autem, et qui cum eo erant, non cognoverunt usque mane: videbant autem luminaria ardentia,',
        30: 'et secutus est eos Ionathas, et non comprehendit eos: transierant enim flumen Eleutherum.',
        31: 'Et divertit Ionathas ad Arabas, qui vocantur Zabadaei, et percussit eos, et accepit spolia eorum.',
        32: 'Et iunxit, et venit Damascum, et perambulabat omnem regionem illam.',
        33: 'Simon autem exiit, et venit usque ad Ascalonem, et ad proxima praesidia: et declinavit in Ioppen, et occupavit eam',
        34: '(audivit enim quod vellent praesidium tradere partibus Demetrii) et posuit ibi custodes ut custodirent eam.',
        35: 'Et reversus est Ionathas, et convocavit seniores populi, et cogitavit cum eis aedificare praesidia in Iudaea,',
        36: 'et aedificare muros in Ierusalem, et exaltare altitudinem magnam inter medium arcis et civitatis, ut separaret eam a civitate, ut esset ipsa singulariter, et neque emant, neque vendant.',
        37: 'Et convenerunt, ut aedificarent civitatem: et cecidit murus, qui erat super torrentem ab ortu solis, et reparavit eum, qui vocatur Caphetetha:',
        38: 'et Simon aedificavit Adiada in Sephela, et munivit eam, et imposuit portas, et seras.',
        39: 'Et cum cogitasset Tryphon regnare Asiae, et assumere diadema, et extendere manum in Antiochum regem:',
        40: 'timens ne forte non permitteret eum Ionathas, sed pugnaret adversus eum, quaerebat comprehendere eum, et occidere. Et exurgens abiit in Bethsan.',
        41: 'Et exivit Ionathas obviam illi cum quadraginta millibus virorum electorum in praelium, et venit Bethsan.',
        42: 'Et vidit Tryphon quia venit Ionathas cum exercitu multo ut extenderet in eum manus, timuit.',
        43: 'et excepit eum cum honore, et commendavit eum omnibus amicis suis, et dedit ei munera: et praecepit exercitibus suis ut obedirent ei, sicut sibi.',
        44: 'Et dixit Ionathae: Ut quid vexasti universum populum, cum bellum nobis non sit?',
        45: 'Et nunc remitte eos in domos suas: elige autem tibi viros paucos, qui tecum sint, et veni mecum Ptolemaidam, et tradam eam tibi, et reliqua praesidia, et exercitum, et universos praepositos negotii, et conversus abibo: propterea enim veni.',
        46: 'Et credidit ei, et fecit sicut dixit: et dimisit exercitum, et abierunt in terram Iuda.',
        47: 'retinuit autem secum tria millia virorum: ex quibus remisit in Galilaeam duo millia, mille autem venerunt cum eo.',
        48: 'Ut autem intravit Ptolemaidam Ionathas, clauserunt portas civitatis Ptolemenses: et comprehenderunt eum: et omnes, qui cum eo intraverant, gladio interfecerunt.',
        49: 'Et misit Tryphon exercitum, et equites in Galilaeam, et in campum magnum ut perderent omnes socios Ionathae.',
        50: 'At illi cum cognovissent quia comprehensus est Ionathas, et periit, et omnes, qui cum eo erant, hortati sunt semetipsos, et exierunt parati in praelium.',
        51: 'Et videntes hi, qui insecuti fuerant, quia pro anima res est illis, reversi sunt:',
        52: 'illi autem venerunt omnes cum pace in terram Iuda. Et planxerunt Ionathan, et eos, qui cum ipso erant, valde: et luxit Israel luctu magno.',
        53: 'Et quaesierunt omnes gentes, quae erant in circuitu eorum, conterere eos. dixerunt enim:',
        54: 'Non habent principem, et adiuvantem: nunc ergo expugnemus illos, et tollamus de hominibus memoriam eorum.',
    },
    13: {
        1: 'Et audivit Simon quod congregavit Tryphon exercitum copiosum ut veniret in terram Iuda, et attereret eam.',
        2: 'Videns quia in tremore populus est, et in timore, ascendit Ierusalem, et congregavit populum:',
        3: 'et adhortans dixit: Vos scitis quanta ego, et fratres mei, et domus patris mei fecimus pro legibus, et pro sanctis praelia, et angustias quales vidimus:',
        4: 'horum gratia perierunt fratres mei omnes propter Israel, et relictus sum ego solus.',
        5: 'Et nunc non mihi contingat parcere animae meae in omni tempore tribulationis: non enim melior sum fratribus meis.',
        6: 'Vindicabo itaque gentem meam, et sancta, natos quoque nostros, et uxores: quia congregatae sunt universae gentes conterere nos inimicitiae gratia.',
        7: 'Et accensus est spiritus populi simul ut audivit sermones istos:',
        8: 'et responderunt voce magna dicentes: Tu es dux noster loco Iudae, et Ionathae fratris tui:',
        9: 'pugna praelium nostrum: et omnia, quaecumque dixeris nobis, faciemus.',
        10: 'Et congregans omnes viros bellatores, acceleravit consummare universos muros Ierusalem, et munivit eam in gyro.',
        11: 'Et misit Ionathan filium Absalomi et cum eo exercitum novum in Ioppen, et eiectis his, qui erant in arce, remansit illic ipse.',
        12: 'Et movit Tryphon a Ptolemaida cum exercitu multo, ut veniret in terram Iuda, et Ionathas cum eo in custodia.',
        13: 'Simon autem applicuit in Addus contra faciem campi.',
        14: 'Et ut cognovit Tryphon quia surrexit Simon loco fratris sui Ionathae: et quia commissurus esset cum eo praelium, misit ad eum legatos,',
        15: 'dicens: Pro argento, quod debebat frater tuus Ionathas in ratione regis, propter negotia, quae habuit, detinuimus eum.',
        16: 'Et nunc mitte argenti talenta centum, et duos filios eius obsides, ut non dimissus fugiat a nobis, et remittemus eum.',
        17: 'Et cognovit Simon quia cum dolo loqueretur secum, iussit tamen dari argentum, et pueros: ne inimicitiam magnam sumeret ad populum Israel, dicentem:',
        18: 'Quia non misit ei argentum, et pueros, propterea periit.',
        19: 'Et misit pueros, et centum talenta: et mentitus est, et non dimisit Ionathan.',
        20: 'Et post haec venit Tryphon intra regionem, ut contereret eam: et gyraverunt per viam, quae ducit Ador: et Simon, et castra eius ambulabant in omnem locum quocumque ibant.',
        21: 'Qui autem in arce erant, miserunt ad Tryphonem legatos, ut festinaret venire per desertum, et mitteret illis alimonias.',
        22: 'Et paravit Tryphon omnem equitatum, ut veniret illa nocte: erat autem nix multa valde, et non venit in Galaaditim.',
        23: 'Et cum appropinquasset Bascaman, occidit Ionathan, et filios eius illic.',
        24: 'Et convertit Tryphon, et abiit in terram suam.',
        25: 'Et misit Simon, et accepit ossa Ionathae fratris sui, et sepelivit ea in Modin civitate patrum eius.',
        26: 'Et planxerunt eum omnis Israel planctu magno, et luxerunt eum dies multos.',
        27: 'Et aedificavit Simon super sepulchrum patris sui et fratrum suorum aedificium altum visu, lapide polito retro et ante:',
        28: 'Et statuit septem pyramidas, unam contra unam patri et matri, et quattuor fratribus:',
        29: 'et his circumposuit columnas magnas: et super columnas arma, ad memoriam aeternam: et iuxta arma naves sculptas, quae viderentur ab omnibus navigantibus mare.',
        30: 'hoc est sepulchrum, quod fecit in Modin, usque in hunc diem.',
        31: 'Tryphon autem cum iter faceret cum Antiocho rege adolescente, dolo occidit eum.',
        32: 'Et regnavit loco eius, et imposuit sibi diadema Asiae, et fecit plagam magnam in terra.',
        33: 'Et aedificavit Simon praesidia Iudaeae, muniens ea turribus excelsis, et muris magnis, et portis, et seris: et posuit alimenta in munitionibus.',
        34: 'Et elegit Simon viros, et misit ad Demetrium regem ut faceret remissionem regioni: quia actus omnes Tryphonis per direptionem fuerant gesti.',
        35: 'Et Demetrius rex ad verba ista respondit ei, et scripsit epistolam talem:',
        36: 'REX Demetrius Simoni summo sacerdoti, et amico regum, et senioribus, et Genti Iudaeorum salutem.',
        37: 'Coronam auream, et bahem, quam misistis, suscepimus: et parati sumus facere vobiscum pacem magnam, et scribere praepositis regis remittere vobis quae indulsimus.',
        38: 'Quaecumque enim constituimus, vobis constant. Munitiones, quas aedificastis, vobis sint.',
        39: 'remittimus quoque ignorantias, et peccata usque in hodiernum diem, et coronam, quam debebatis: et siquid aliud erat tributarium in Ierusalem, iam non sit tributarium.',
        40: 'Et si qui ex vobis apti sunt conscribi inter nostros, conscribantur, et sit inter nos pax.',
        41: 'Anno centesimo septuagesimo ablatum est iugum Gentium ab Israel.',
        42: 'Et coepit populus Israel scribere in tabulis, et gestis publicis, anno primo sub Simone summo sacerdote, magno duce, et principe Iudaeorum.',
        43: 'In diebus illis applicuit Simon ad Gazam, et circumdedit eam castris, et fecit machinas, et applicuit ad civitatem, et percussit turrem unam, et comprehendit eam.',
        44: 'Et qui eruperant, erant intra machinam in civitatem: et factus est motus magnus in civitate.',
        45: 'Et ascenderunt qui erant in civitate cum uxoribus, et filiis supra murum scissis tunicis suis, et clamaverunt voce magna, postulantes a Simone dextras sibi dari,',
        46: 'et dixerunt: Non nobis reddas secundum malitias nostras, sed secundum misericordias tuas et serviemus tibi.',
        47: 'Et flexus Simon non debellavit eos: eiecit tamen eos de civitate, et mundavit aedes, in quibus fuerant simulacra, et tunc intravit in eam cum hymnis benedicens Dominum:',
        48: 'et eiecta ab ea omni immunditia, collocavit in ea viros, qui legem facerent: et munivit eam, et fecit sibi habitationem.',
        49: 'Qui autem erant in arce Ierusalem, prohibebantur egredi et ingredi regionem, et emere, ac vendere: et esurierunt valde, et multi ex eis fame perierunt,',
        50: 'et clamaverunt ad Simonem ut dextras acciperent: et dedit illis: et eiecit eos inde, et mundavit arcem a contaminationibus:',
        51: 'et intraverunt in eam tertia et vigesima die secundi mensis, anno centesimo septuagesimo primo cum laude, et ramis palmarum, et cinyris, et cymbalis, et nablis, et hymnis, et canticis, quia contritus est inimicus magnus ex Israel.',
        52: 'Et constituit ut omnibus annis agerentur dies hi cum laetitia.',
        53: 'Et munivit montem templi, qui erat secus arcem, et habitavit ibi ipse, et qui cum eo erant.',
        54: 'Et vidit Simon Ioannem filium suum, quod fortis praelii vir esset: et posuit eum ducem virtutum universarum: et habitavit in Gazaris.',
    },
    14: {
        1: 'Anno centesimo septuagesimo secundo congregavit rex Demetrius exercitum suum, et abiit in Mediam ad contrahenda sibi auxilia, ut expugnaret Tryphonem.',
        2: 'Et audivit Arsaces rex Persidis, et Mediae, quia intravit Demetrius confines suos, et misit unum de principibus suis ut comprehenderet eum vivum, et adduceret eum ad se.',
        3: 'Et abiit, et percussit castra Demetrii: et comprehendit eum, et duxit eum ad Arsacem, et posuit eum in custodiam.',
        4: 'Et siluit omnis terra Iuda omnibus diebus Simonis, et quaesivit bona genti suae: et placuit illis potestas eius, et gloria eius omnibus diebus.',
        5: 'Et cum omni gloria sua accepit Ioppen in portum, et fecit introitum in insulis maris.',
        6: 'Et dilatavit fines gentis suae, et obtinuit regionem.',
        7: 'Et congregavit captivitatem multam, et dominatus est Gazarae, et Bethsurae, et arci: et abstulit immunditias ex ea, et non erat qui resisteret ei.',
        8: 'Et unusquisque colebat terram suam cum pace: et terra Iuda dabat fructus suos, et ligna camporum fructum suum.',
        9: 'Seniores in plateis sedebant omnes, et de bonis terrae tractabant, et iuvenes induebant se gloriam, et stolas belli.',
        10: 'Et civitatibus tribuebat alimonias, et constituebat eas ut essent vasa munitionis quoadusque nominatum est nomen gloriae eius usque ad extremum terrae.',
        11: 'Fecit pacem super terram, et laetatus est Israel laetitia magna.',
        12: 'Et sedit unusquisque sub vite sua, et sub ficulnea sua: et non erat qui eos terreret.',
        13: 'Defecit impugnans eos super terram: reges contriti sunt in diebus illis.',
        14: 'Et confirmavit omnes humiles populi sui, et legem exquisivit, et abstulit omnem iniquum et malum:',
        15: 'sancta glorificavit, et multiplicavit vasa sanctorum.',
        16: 'Et auditum est Romae quia defunctus esset Ionathas: et usque in Spartiatas: et contristati sunt valde.',
        17: 'Ut audierunt autem quod Simon frater eius factus esset summus sacerdos loco eius, et ipse obtineret omnem regionem, et civitates in ea;',
        18: 'scripserunt ad eum in tabulis aereis, ut renovarent amicitias, et societatem quam fecerant cum Iuda, et cum Ionatha fratribus eius.',
        19: 'Et lectae sunt in conspectu ecclesiae in Ierusalem. Et hoc exemplum epistolarum, quas Spartiatae miserunt:',
        20: 'SPARTIANORUM principes, et civitates, Simoni sacerdoti magno, et senioribus, et sacerdotibus, et reliquo populo Iudaeorum, fratribus, salutem.',
        21: 'Legati, qui missi sunt ad populum nostrum, nunciaverunt nobis de vestra gloria, et honore, ac laetitia: et gavisi sumus in introitu eorum.',
        22: 'Et scripsimus quae ab eis erant dicta in conciliis populi, sic: Numenius Antiochi, et Antipater Iasonis filius, legati Iudaeorum, venerunt ad nos, renovantes nobiscum amicitiam pristinam.',
        23: 'Et placuit populo excipere viros gloriose, et ponere exemplum sermonum eorum in segregatis populi libris, ut sit ad memoriam populo Spartiatarum. Exemplum autem horum scripsimus Simoni magno sacerdoti.',
        24: 'Post haec autem misit Simon Numenium Romam, habentem clypeum aureum magnum, pondo mnarum mille, ad statuendam cum eis societatem. Cum autem audisset populus Romanus',
        25: 'sermones istos, dixerunt: Quam gratiarum actionem reddemus Simoni, et filiis eius?',
        26: 'Restituit enim ipse fratres suos, et expugnavit inimicos Israel ab eis, et statuerunt ei libertatem, et descripserunt in tabulis aereis, et posuerunt in titulis in monte Sion.',
        27: 'Et hoc est exemplum scripturae: OCTAVA decima die mensis Elul, anno centesimo septuagesimo secundo, anno tertio sub Simone sacerdote magno in Asaramel,',
        28: 'in conventu magno sacerdotum, et populi, et principum gentis, et seniorum regionis, nota facta sunt haec: Quoniam frequenter facta sunt praelia in regione nostra.',
        29: 'Simon autem Mathathiae filius ex filiis Iarib, et fratres eius dederunt se periculo, et restiterunt adversariis gentis suae, ut starent sancta ipsorum, et lex: et gloria magna glorificaverunt gentem suam.',
        30: 'Et congregavit Ionathas gentem suam, et factus est illis sacerdos magnus, et appositus est ad populum suum.',
        31: 'Et voluerunt inimici eorum calcare, et atterere regionem ipsorum, et extendere manus in sancta eorum.',
        32: 'Tunc restitit Simon, et pugnavit pro gente sua, et erogavit pecunias multas, et armavit viros virtutis gentis suae, et dedit illis stipendia:',
        33: 'et munivit civitates Iudaeae, et Bethsuram, quae erat in finibus Iudaeae, ubi erant arma hostium antea: et posuit illic praesidium viros Iudaeos.',
        34: 'Et Ioppen munivit, quae erat ad mare: et Gazaram, quae est in finibus Azoti, in qua hostes antea habitabant, et collocavit illic Iudaeos: et quaecumque apta erant ad correptionem eorum, posuit in eis.',
        35: 'Et vidit populus actum Simonis, et gloriam, quam cogitabat facere genti suae, et posuerunt eum ducem suum, et principem sacerdotum, eo quod ipse fecerat haec omnia, et iustitiam, et fidem, quam conservavit genti suae, et exquisivit omni modo exaltare populum suum.',
        36: 'Et in diebus eius prosperatum est in manibus eius, ut tollerentur gentes de regione ipsorum, et qui in civitate David erant in Ierusalem in arce, de qua procedebant, et contaminabant omnia, quae in circuitu sanctorum sunt, et inferebant plagam magnam castitati:',
        37: 'et collocavit in ea viros Iudaeos ad tutamentum regionis, et civitatis, et exaltavit muros in Ierusalem.',
        38: 'Et rex Demetrius statuit illi summum sacerdotium.',
        39: 'Secundum haec fecit eum amicum suum, et glorificavit eum gloria magna.',
        40: 'Audivit enim quod appellati sunt Iudaei a Romanis amici, et socii, et fratres, et quia susceperunt legatos Simonis gloriose:',
        41: 'et quia Iudaei, et sacerdotes eorum consenserunt eum esse ducem suum, et summum sacerdotem in aeternum, donec surgat propheta fidelis:',
        42: 'et ut sit super eos dux, et ut cura esset illi pro sanctis, et ut constitueret praepositos super opera eorum, et super regionem, et super arma, et super praesidia:',
        43: 'et cura sit illi de sanctis: et ut audiatur ab omnibus, et scribantur in nomine eius omnes conscriptiones in regione: et ut operiatur purpura, et auro:',
        44: 'et ne liceat ulli ex populo, et ex sacerdotibus irritum facere aliquid horum, et contradicere his, quae ab eo dicuntur, aut convocare conventum in regione sine ipso: et vestiri purpura, et uti fibula aurea.',
        45: 'qui autem fecerit extra haec, aut irritum fecerit aliquid horum, reus erit.',
        46: 'Et complacuit omni populo statuere Simonem, et facere secundum verba ista.',
        47: 'Et suscepit Simon, et placuit ei ut summo sacerdotio fungeretur, et esset dux, et princeps gentis Iudaeorum, et sacerdotum, et praeesset omnibus.',
        48: 'Et scripturam istam dixerunt ponere in tabulis aereis, et ponere eas in peribolo sanctorum, in loco celebri:',
        49: 'exemplum autem eorum ponere in aerario, ut habeat Simon, et filii eius.',
    },
    15: {
        1: 'Et misit rex Antiochus filius Demetrii epistolas ab insulis maris Simoni sacerdoti, et principi gentis Iudaeorum, et universae genti:',
        2: 'et erant continentes hunc modum: REX Antiochus Simoni sacerdoti magno, et genti Iudaeorum salutem.',
        3: 'Quoniam quidem pestilentes obtinuerunt regnum patrum nostrorum, volo autem vendicare regnum, et restituere illud sicut erat antea: et electam feci multitudinem exercitus, et feci naves bellicas.',
        4: 'Volo autem procedere per regionem ut ulciscar in eos, qui corruperunt regionem nostram, et qui desolaverunt civitates multas in regno meo.',
        5: 'Nunc ergo statuo tibi omnes oblationes, quas remiserunt tibi ante me omnes reges, et quaecumque alia dona remiserunt tibi:',
        6: 'et permitto tibi facere percussuram proprii numismatis in regione tua:',
        7: 'Ierusalem autem sanctam esse, et liberam: et omnia arma, quae fabricata sunt, et praesidia, quae construxisti, quae tenes, maneant tibi.',
        8: 'Et omne debitum regis: et quae futura sunt regi, ex hoc, et in totum tempus remittuntur tibi.',
        9: 'Cum autem obtinuerimus regnum nostrum, glorificabimus te, et gentem tuam, et templum gloria magna ita ut manifestetur gloria vestra in universa terra.',
        10: 'Anno centesimo septuagesimo quarto exiit Antiochus in terram patrum suorum, et convenerunt ad eum omnes exercitus, ita ut pauci relicti essent cum Tryphone.',
        11: 'Et insecutus est eum Antiochus rex, et venit Doram fugiens per maritimam.',
        12: 'sciebat enim quod congregata sunt mala in eum, et reliquit eum exercitus.',
        13: 'et applicuit Antiochus super Doram cum centum viginti millibus virorum belligeratorum, et octo millibus equitum:',
        14: 'et circuivit civitatem, et naves a mari accesserunt: et vexabant civitatem a terra, et mari, et neminem sinebant ingredi, vel egredi.',
        15: 'Venit autem Numenius, et qui cum eo fuerant, ab urbe Roma, habentes epistolas regibus, et regionibus scriptas, in quibus continebantur haec:',
        16: 'LUCIUS consul Romanorum, Ptolemaeo regi salutem.',
        17: 'Legati Iudaeorum venerunt ad nos amici nostri, renovantes pristinam amicitiam, et societatem, missi a Simone principe Sacerdotum, et populo Iudaeorum.',
        18: 'Attulerunt autem et clypeum aureum mnarum mille.',
        19: 'Placuit itaque nobis scribere regibus, et regionibus, ut non inferant illis mala, neque impugnent eos, et civitates eorum, et regiones eorum: et ut non ferant auxilium pugnantibus adversus eos.',
        20: 'Visum autem est nobis accipere ab eis clypeum.',
        21: 'Siqui ergo pestilentes fugerint de regione ipsorum ad vos, tradite eos Simoni principi sacerdotum, ut vindicet in eos secundum legem suam.',
        22: 'Haec eadem scripta sunt Demetrio regi, et Attalo, et Arabae, et Arsaci,',
        23: 'et in omnes regiones: et Sampsamae, et Spartiatis, et in Delum, et in Myndum, et in Sicyonem, et in Cariam, et in Samum, et in Pamphyliam, et in Lyciam, et in Alicarnassum, et in Coo, et in Siden, et in Aradon, et in Rhodum, et in Phaselidem, et in Cortynam, et Gnidum, et Cyprum, et Cyrenen.',
        24: 'Exemplum autem eorum scripserunt Simoni principi sacerdotum, et populo Iudaeorum.',
        25: 'Antiochus autem rex applicuit castra in Doram secundo, admovens ei semper manus, et machinas faciens: et conclusit Tryphonem, ne procederet.',
        26: 'et misit ad eum Simon duo millia virorum electorum in auxilium, et argentum, et aurum, et vasa copiosa:',
        27: 'et noluit ea accipere, sed rupit omnia, quae pactus est cum eo antea, et alienavit se ab eo.',
        28: 'Et misit ad eum Athenobium unum de amicis suis, ut tractaret cum ipso, dicens: Vos tenetis Ioppen, et Gazaram, et arcem, quae est in Ierusalem, civitates regni mei:',
        29: 'fines earum desolastis, et fecistis plagam magnam in terra, et dominati estis per loca multa in regno meo.',
        30: 'Nunc ergo tradite civitates, quas occupastis, et tributa locorum, in quibus dominati estis extra fines Iudaeae.',
        31: 'sin autem, date pro illis quingenta talenta argenti, et exterminii, quod exterminastis, et tributorum civitatum alia talenta quingenta: sin autem, veniemus, et expugnabimus vos.',
        32: 'Et venit Athenobius amicus regis in Ierusalem, et vidit gloriam Simonis, et claritatem in auro, et argento, et apparatum copiosum: et obstupuit: et retulit ei verba Regis.',
        33: 'Et respondit ei Simon, et dixit ei: Neque alienam terram sumpsimus, neque alienam detinemus: sed hereditatem patrum nostrorum, quae iniuste ab inimicis nostris aliquo tempore possessa est.',
        34: 'Nos vero tempus habentes, vendicamus hereditatem patrum nostrorum.',
        35: 'Nam de Ioppe, et Gazara quae expostulas, ipsi faciebant in populo plagam magnam, et in regione nostra: horum damus talenta centum. Et non respondit ei Athenobius verbum.',
        36: 'Reversus autem cum ira ad regem, renunciavit ei verba ista, et gloriam Simonis, et universa, quae vidit, et iratus est rex ira magna.',
        37: 'Tryphon autem fugit navi in Orthosiada.',
        38: 'Et constituit rex Cendebaeum ducem maritimum, et exercitum peditum et equitum dedit illi.',
        39: 'Et mandavit illi movere castra contra faciem Iudaeae: et mandavit ei aedificare Gedorem, et obstruere portas civitatis, et debellare populum. Rex autem persequebatur Typhonem.',
        40: 'Et pervenit Cendebaeus Iamniam, et coepit irritare plebem, et conculcare Iudaeam, et captivare populum, et interficere, et aedificare Cedronem.',
        41: 'Et collocavit illic equites, et exercitum: ut egressi perambularent viam Iudaeae, sicut constituit ei rex.',
    },
    16: {
        1: 'Et ascendit Ioannes de Gazaris, et nunciavit Simoni patri suo quae fecit Cendebaeus in populo ipsorum.',
        2: 'Et vocavit Simon duos filios seniores, Iudam, et Ioannem, et ait illis: Ego, et fratres mei, et domus patris mei expugnavimus hostes Israel ab adolescentia usque in hunc diem: et prosperatum est in manibus nostris liberare Israel aliquoties.',
        3: 'Nunc autem senui, sed estote loco meo, et fratres mei, et egressi pugnate pro gente nostra: auxilium vero de caelo vobiscum sit.',
        4: 'Et elegit de regione viginti millia virorum belligeratorum, et equites; et profecti sunt ad Cendebaeum: et dormierunt in Modin.',
        5: 'Et surrexerunt mane, et abierunt in campum: et ecce exercitus copiosus in obviam illis peditum, et equitum, et fluvius torrens erat inter medium ipsorum.',
        6: 'Et admovit castra contra faciem eorum ipse, et populus eius, et vidit populum trepidantem ad transfretandum torrentem, et transfretavit primus: et viderunt eum viri, et transierunt post eum.',
        7: 'Et divisit populum et equites in medio peditum: erat autem equitatus adversariorum copiosus nimis.',
        8: 'Et exclamaverunt sacris tubis, et in fugam conversus est Cendebaeus, et castra eius: et ceciderunt ex eis multi vulnerati: residui autem in munitionem fugerunt.',
        9: 'Tunc vulneratus est Iudas frater Ioannis: Ioannes autem insecutus est eos, donec venit Cedronem, quam aedificavit:',
        10: 'et fugerunt usque ad turres, quae erant in agris Azoti, et succendit eas igne. Et ceciderunt ex illis duo millia virorum, et reversus est in Iudaeam in pace.',
        11: 'et Ptolemaeus filius Abobi constitutus erat dux in campo Iericho, et habebat argentum, et aurum multum.',
        12: 'erat enim gener summi sacerdotis.',
        13: 'Et exaltatum est cor eius, et volebat obtinere regionem, et cogitabat dolum adversus Simonem, et filios eius, ut tolleret eos.',
        14: 'Simon autem, perambulans civitates, quae erant in regione Iudaeae, et solicitudinem gerens earum, descendit in Iericho ipse, et Mathathias filius eius, et Iudas, anno centesimo septuagesimo septimo, mense undecimo: hic est mensis Sabath.',
        15: 'Et suscepit eos filius Abobi in munitiunculam, quae vocatur Doch, cum dolo, quam aedificavit: et fecit eis convivium magnum, et abscondit illic viros.',
        16: 'Et cum inebriatus esset Simon, et filii eius, surrexit Ptolemaeus cum suis, et sumpserunt arma sua, et intraverunt in convivium, et occiderunt eum, et duos filios eius, et quosdam pueros eius.',
        17: 'et fecit deceptionem magnam in Israel, et reddidit mala pro bonis.',
        18: 'Et scripsit haec Ptolemaeus, et misit regi ut mitteret ei exercitum in auxilium, et traderet ei regionem, et civitates eorum, et tributa.',
        19: 'Et misit alios in Gazaram tollere Ioannem: et tribunis misit epistolas, ut venirent ad se, et daret eis argentum, et aurum, et dona.',
        20: 'Et alios misit occupare Ierusalem, et montem templi.',
        21: 'Et praecurrens quidam, nunciavit Ioanni in Gazara, quia periit pater eius, et fratres eius, et quia misit te quoque interfici.',
        22: 'Ut audivit autem, vehementer expavit: et comprehendit viros, qui venerant perdere eum, et occidit eos: cognovit enim quia quaerebant eum perdere.',
        23: 'Et cetera sermonum Ioannis, et bellorum eius, et bonarum virtutum, quibus fortiter gessit, et aedificii murorum, quos extruxit, et rerum gestarum eius:',
        24: 'ecce haec scripta sunt in libro dierum sacerdotii eius, ex quo factus est princeps sacerdotum post patrem suum.',
    },
}
